/**
 * @param {string} s
 * @return {number}
 */
var longestValidParentheses = function(s) {
  if (!s.length) {
    return 0;
  }

  const stack = [-1];
  let max = 0;

  for (let i = 0; i < s.length; i++) {
    if (s[i] === '(') {
      stack.push(i);
    } else {
      stack.pop();
      if (!stack.length) {
        stack.push(i);
      } else {
        max = Math.max(max, i - stack[stack.length - 1]);
      }
    }
  }

  return max;
};

