    for (let j = 0; j < board[0].length; j++) {
      if (board[i][j] === '-') {
        board[i][j] = 'O';
      } else {
        board[i][j] = 'X';
      }
    }
  }

  function dfs(i, j) {
    if (i < 0 || i >= board.length || j < 0 || j >= board[i].length
        || board[i][j] === '-' || board[i][j] === 'X') {
      return;
