  const partitions = new Array(s.length).fill(0);

  for (let i = 0; i < s.length; i++) {
    let offset = i;
    for (let j = 0; j <= i; j++) {
      if (s[j] === s[i] && (i - j <= 1 || isPalindrome[j + 1][i - 1])) {
        isPalindrome[j][i] = true;
