/**
 * @param {number[]} nums
 */
var NumArray = function(nums) {
  this.n = nums.length;
  this.tree = new Array(2 * this.n);

  for (let i = 0; i < this.n; i++) {
    this.tree[this.n + i] = nums[i];
  }

  for (let i = this.n - 1; i > 0; i--) {
    this.tree[i] = this.tree[i * 2] + this.tree[i * 2 + 1];
  }
};

/**
 * @param {number} index
 * @param {number} val
 * @return {void}
 */
NumArray.prototype.update = function(index, val) {
  let position = this.n + index;
  this.tree[position] = val;

  while (position) {
    let left = position;
    let right = position;
    if (position % 2 === 0) {
      right = position + 1;
    } else {
      left = position - 1;
    }
    this.tree[position >> 1] = this.tree[left] + this.tree[right];
    position >>= 1;
  }
};

/**
 * @param {number} left
 * @param {number} right
 * @return {number}
 */
NumArray.prototype.sumRange = function(left, right) {
  let sum = 0;
  let l = this.n + left;
  let r = this.n + right + 1;

  while (l < r) {
    if (l % 2 == 1) {
      sum += this.tree[l++];
    }
    if (r % 2 == 1) {
      sum += this.tree[--r];
    }
    l >>= 1;
    r >>= 1;
  }

  return sum;
};

range-sum-query-2d-mutable.solution:
/**
 * @param {number[][]} matrix
 */
var NumMatrix = function(matrix) {
  this.rows = matrix.length;
  this.cols = matrix[0].length;
  this.matrix = matrix;
  this.tree = new Array(this.rows + 1).fill().map(() => new Array(this.cols + 1).fill(0));

  for (let i = 0; i < this.rows; i++) {
    for (let j = 0; j < this.cols; j++) {
      this.updateTree(i + 1, j + 1, matrix[i][j]);
    }
  }
};

/**
 * @param {number} row
 * @param {number} col
 * @param {number} val
 * @return {void}
 */
NumMatrix.prototype.updateTree = function(row, col, val) {
  while (row <= this.rows) {
    let c = col;
    while (c <= this.cols) {
      this.tree[row][c] += val;
      c += c & (-c);
    }
    row += row & (-row);
  }
};

/**
 * @param {number} row
 * @param {number} col
 * @return {number}
 */
NumMatrix.prototype.getSum = function(row, col) {
  let sum = 0;
  while (row > 0) {
    let c = col;
    while (c > 0) {
      sum += this.tree[row][c];
      c -= c & (-c);
    }
    row -= row & (-row);
  }
  return sum;
};

/**
 * @param {number} row
 * @param {number} col
 * @param {number} val
 * @return {void}
 */
NumMatrix.prototype.update = function(row, col, val) {
  const diff = val - this.matrix[row][col];
  this.matrix[row][col] = val;
  this.updateTree(row + 1, col + 1, diff);
};

/**
 * @param {number} row1
 * @param {number} col1
 * @param {number} row2
 * @param {number} col2
 * @return {number}
 */
NumMatrix.prototype.sumRegion = function(row1, col1, row2, col2) {
  return this.getSum(row2 + 1, col2 + 1)
    - this.getSum(row2 + 1, col1)
    - this.getSum(row1, col2 + 1)
    + this.getSum(row1, col1);
};

