/**
 * @param {ListNode} head
 * @return {ListNode}
 */
var oddEvenList = function(head) {
  if (!head) return head;

  const even = head.next;
  let odd = head;

  while (odd.next && odd.next.next) {
    const pointer = odd.next;
    odd.next = odd.next.next;
    odd = odd.next;
