NestedIterator.prototype.hasNext = function() {
  while (this.stack.length > 0 && !this.stack[this.stack.length - 1].isInteger()) {
    const nested = this.stack.pop().getList();
    this.flatten(nested);
  }
  return this.stack.length > 0;
};

