/**
 * @param {number} n
 */
var TicTacToe = function(n) {
  this.size = n;
  this.rows = new Array(n).fill(0);
  this.cols = new Array(n).fill(0);
  this.diagonal = 0;
  this.antiDiagonal = 0;
};

/**
 * @param {number} row
 * @param {number} col
 * @param {number} player
 * @return {number}
 */
TicTacToe.prototype.move = function(row, col, player) {
  const value = player === 1 ? 1 : -1;

  this.rows[row] += value;
  this.cols[col] += value;

  if (row === col) {
    this.diagonal += value;
  }

  if (row + col === this.size - 1) {
    this.antiDiagonal += value;
  }

  if (Math.abs(this.rows[row]) === this.size || Math.abs(this.cols[col]) === this.size
    || Math.abs(this.diagonal) === this.size || Math.abs(this.antiDiagonal) === this.size) {
    return player;
  }

  return 0;
};

