  const pointSet = new Set(points.map(([x, y]) => `${x},${y}`));
  let minX = Infinity;
  let maxX = -Infinity;

  for (const [x] of points) {
    minX = Math.min(minX, x);
    maxX = Math.max(maxX, x);
  }

  const sum = minX + maxX;
  for (const [x, y] of points) {
