/**
 * // Definition for a _Node.
 * function _Node(val, left, right) {
 *      this.val = val;
 *      this.left = left;
 *      this.right = right;
 *  };
 */

/**
 * @param {_Node} root
 * @return {_Node}
 */
var treeToDoublyList = function(root) {
  if (!root) return null;

  let first = null;
  let last = null;

  inorder(root);

  last.right = first;
  first.left = last;

  return first;

  function inorder(node) {
    if (!node) return;

    inorder(node.left);

    if (last) {
      last.right = node;
      node.left = last;
    } else {
      first = node;
    }
    last = node;

    inorder(node.right);
  }
};

