/**
 * // Definition for a _Node.
 * function _Node(val,children) {
 *    this.val = val;
 *    this.children = children;
 * };
 */

/**
 * @param {_Node|null} root
 * @return {number[][]}
 */
var levelOrder = function(root) {
  if (!root) return [];

  const result = [];
  const queue = [root];

  while (queue.length) {
    const [level, current] = [queue.length, []];
    for (let i = 0; i < level; i++) {
      const node = queue.shift();
      current.push(node.val);
      queue.push(...node.children);
    }
    result.push(current);
  }

  return result;
};

flatten-a-multilevel-doubly-linked-list.solution:
/**
 * // Definition for a _Node.
 * function _Node(val,prev,next,child) {
 *    this.val = val;
 *    this.prev = prev;
 *    this.next = next;
 *    this.child = child;
 * };
 */

/**
 * @param {_Node} head
 * @return {_Node}
 */
var flatten = function(head) {
  if (!head) return null;

  let current = head;
  while (current) {
    if (!current.child) {
      current = current.next;
    } else {
      const { child, next } = current;
      current.child = null;
      current.next = child;
      child.prev = current;

      let tail = child;
      while (tail.next) {
        tail = tail.next;
      }

      tail.next = next;
      if (next) {
        next.prev = tail;
      }
      current = current.next;
    }
  }

  return head;
};

