/**
 * // Definition for a _Node.
 * function _Node(val,children) {
 *    this.val = val;
 *    this.children = children;
 * };
 */

/**
 * Definition for a binary tree node.
 * function TreeNode(val) {
 *     this.val = val;
 *     this.left = this.right = null;
 * }
 */

class Codec {
  constructor() {}

  encode = function(root) {
    if (!root) return null;

    const binaryRoot = new TreeNode(root.val);

    if (root.children.length > 0) {
      binaryRoot.left = this.encode(root.children[0]);
    }

    let sibling = binaryRoot.left;
    for (let i = 1; i < root.children.length; i++) {
      if (sibling) {
        sibling.right = this.encode(root.children[i]);
        sibling = sibling.right;
      }
    }

    return binaryRoot;
  };

  decode = function(root) {
    if (!root) return null;

    const updated = new _Node(root.val, []);
    let sibling = root.left;
    while (sibling) {
      updated.children.push(this.decode(sibling));
      sibling = sibling.right;
    }

    return updated;
  };
}

all-oone-data-structure.solution:
var AllOne = function() {
  this.map = new Map();
  this.head = { count: 0, keys: new Set(), prev: null, next: null };
  this.tail = { count: Infinity, keys: new Set(), prev: this.head, next: null };
  this.head.next = this.tail;
};

/**
 * @param {string} key
 * @return {void}
 */
AllOne.prototype.inc = function(key) {
  const node = this.map.get(key) || this.head;
  const count = node.count + 1;
  let next = node.next;

  if (next.count !== count) {
    next = { count, keys: new Set(), prev: node, next: node.next };
    node.next.prev = next;
    node.next = next;
  }

  next.keys.add(key);
  node.keys.delete(key);
  this.map.set(key, next);

  if (node !== this.head && node.keys.size === 0) {
    node.prev.next = node.next;
    node.next.prev = node.prev;
  }
};

/**
 * @param {string} key
 * @return {void}
 */
AllOne.prototype.dec = function(key) {
  const node = this.map.get(key);
  const count = node.count - 1;

  node.keys.delete(key);

  if (count === 0) {
    this.map.delete(key);
  } else {
    let prev = node.prev;
    if (prev.count !== count) {
      prev = { count, keys: new Set(), prev: node.prev, next: node };
      node.prev.next = prev;
      node.prev = prev;
    }
    prev.keys.add(key);
    this.map.set(key, prev);
  }

  if (node.keys.size === 0) {
    node.prev.next = node.next;
    node.next.prev = node.prev;
  }
};

/**
 * @return {string}
 */
AllOne.prototype.getMaxKey = function() {
  const node = this.tail.prev;
  return node === this.head ? '' : node.keys.values().next().value;
};

/**
 * @return {string}
 */
AllOne.prototype.getMinKey = function() {
  const node = this.head.next;
  return node === this.tail ? '' : node.keys.values().next().value;
};

minimum-genetic-mutation.solution:
/**
 * @param {string} startGene
 * @param {string} endGene
 * @param {string[]} bank
 * @return {number}
 */
var minMutation = function(startGene, endGene, bank) {
  const set = new Set(bank);
  if (!set.has(endGene)) return -1;

  const queue = [[startGene, 0]];
  const seen = new Set([startGene]);

  while (queue.length) {
    const [gene, steps] = queue.shift();
    if (gene === endGene) return steps;

    for (let i = 0; i < 8; i++) {
      for (const char of ['A', 'C', 'G', 'T']) {
        if (char !== gene[i]) {
          const next = gene.slice(0, i) + char + gene.slice(i + 1);
          if (set.has(next) && !seen.has(next)) {
            queue.push([next, steps + 1]);
            seen.add(next);
          }
        }
      }
    }
  }

  return -1;
};

