    const distances = new Map();
    for (let j = 0; j < points.length; j++) {
      if (i === j) continue;
      const d = (points[i][0] - points[j][0]) ** 2 + (points[i][1] - points[j][1]) ** 2;
      distances.set(d, (distances.get(d) || 0) + 1);
    }
    for (const d of distances.values()) {
