/**
 * @param {number[][]} transactions
 * @return {number}
 */
var minTransfers = function(transactions) {
  const balances = new Array(12).fill(0);

  for (const [from, to, amount] of transactions) {
    balances[from] -= amount;
    balances[to] += amount;
  }

  const debts = balances.filter(balance => balance !== 0);
  return helper(0, 0);

  function helper(index, count) {
    if (index === debts.length) return count;

    if (debts[index] === 0) return helper(index + 1, count);

    let minTransactions = Infinity;
    const currentDebt = debts[index];

    for (let i = index + 1; i < debts.length; i++) {
      if (debts[i] * currentDebt < 0) {
        debts[i] += currentDebt;
        minTransactions = Math.min(minTransactions, helper(index + 1, count + 1));
        debts[i] -= currentDebt;
      }
    }

    return minTransactions;
  }
};

count-the-repetitions.solution:
/**
 * @param {string} s1
 * @param {number} n1
 * @param {string} s2
 * @param {number} n2
 * @return {number}
 */
var getMaxRepetitions = function(s1, n1, s2, n2) {
  const pattern = {};
  let s2Count = 0;
  let s2Index = 0;

  for (let i = 0; i < n1; i++) {
    for (let j = 0; j < s1.length; j++) {
      if (s1[j] === s2[s2Index]) {
        s2Index++;
        if (s2Index === s2.length) {
          s2Index = 0;
          s2Count++;
        }
      }
    }

    if (pattern[s2Index]) {
      const [prevIndex, prevCount] = pattern[s2Index];
      const remainingCycles = Math.floor((n1 - i - 1) / (i - prevIndex));
      i += remainingCycles * (i - prevIndex);
      s2Count += remainingCycles * (s2Count - prevCount);
    } else {
      pattern[s2Index] = [i, s2Count];
    }
  }

  return Math.floor(s2Count / n2);
};

