  const map = new Map();

  function isValid(word) {
    if (map.has(word)) return map.get(word);
    for (let i = 1; i < word.length; i++) {
      const suffix = word.slice(i);
      if (set.has(word.slice(0, i)) && (set.has(suffix) || isValid(suffix))) {
        map.set(word, true);
        return true;
      }
    }
    map.set(word, false);
    return false;
  }

  return words.filter(word => word.length > 0 && isValid(word));
};

matchsticks-to-square.solution:
/**
 * @param {number[]} matchsticks
 * @return {boolean}
 */
var makesquare = function(matchsticks) {
  if (matchsticks.length < 4) return false;
  const sum = matchsticks.reduce((a, b) => a + b);
  if (sum % 4) return false;

  const side = sum / 4;
  matchsticks.sort((a, b) => b - a);
  if (matchsticks[0] > side) return false;

  const sides = [0, 0, 0, 0];
  return (function backtrack(index) {
    if (index === matchsticks.length) return true;
    for (let i = 0; i < 4; i++) {
      if (sides[i] + matchsticks[index] <= side) {
        sides[i] += matchsticks[index];
        if (backtrack(index + 1)) return true;
        sides[i] -= matchsticks[index];
        if (!sides[i]) break;
      }
    }
    return false;
  })(0);
};

