 * @param {number[]} p3
 * @param {number[]} p4
 * @return {boolean}
 */
var validSquare = function(p1, p2, p3, p4) {
  const helper = (a, b) => (a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2;
  const points = [p1, p2, p3, p4];
  const set = new Set();

  for (let i = 0; i < 4; i++) {
    for (let j = i + 1; j < 4; j++) {
      const d = helper(points[i], points[j]);
      if (!d) {
        return false;
      }
      set.add(d);
    }
  }

  return set.size === 2;
};

