/**
 * @param {number} n
 * @return {number}
 */
var findIntegers = function(n) {
  const binary = n.toString(2);
  const dp = new Array(binary.length + 1).fill(0);
  let result = 0;

  dp[0] = 1;
  dp[1] = 2;

  for (let i = 2; i <= binary.length; i++) {
    dp[i] = dp[i - 1] + dp[i - 2];
  }

  for (let i = 0, previous = 0; i < binary.length; i++) {
    if (binary[i] === '1') {
      result += dp[binary.length - i - 1];
      if (previous === 1) {
        return result;
      }
      previous = 1;
    } else {
      previous = 0;
    }
  }

  return result + 1;
};

design-compressed-string-iterator.solution:
/**
 * @param {string} compressedString
 */
var StringIterator = function(compressedString) {
  this.segments = [];
  this.currentIndex = 0;
  this.currentCount = 0;

  let i = 0;
  while (i < compressedString.length) {
    const character = compressedString[i];
    i++;
    let count = '';
    while (i < compressedString.length && /\d/.test(compressedString[i])) {
      count += compressedString[i];
      i++;
    }
    this.segments.push([character, parseInt(count)]);
  }
};

/**
 * @return {character}
 */
StringIterator.prototype.next = function() {
  if (!this.hasNext()) {
    return ' ';
  }

  if (this.currentCount === 0) {
    this.currentCount = this.segments[this.currentIndex][1];
  }

  const character = this.segments[this.currentIndex][0];
  this.currentCount--;

  if (this.currentCount === 0) {
    this.currentIndex++;
  }

  return character;
};

/**
 * @return {boolean}
 */
StringIterator.prototype.hasNext = function() {
  return this.currentIndex < this.segments.length;
};

