  const map = new Map();
  let maxValue = 0;
  let maxCount = 0;

  tasks.forEach(key => {
    const value = map.has(key) ? map.get(key) + 1 : 1;
    map.set(key, value);

    if (value > maxValue) {
      maxValue = value;
      maxCount = 1;
    } else if (value === maxValue) {
      maxCount++;
    }
  });

