/**
 * @param {number} n
 * @param {number} k
 * @return {number}
 */
var kInversePairs = function(n, k) {
  const MOD = 1e9 + 7;
  const dp = new Array(k + 1).fill(0);

  dp[0] = 1;
  for (let i = 1; i <= n; i++) {
    const previous = dp.slice();
    dp[0] = 1;
    for (let j = 1; j <= k; j++) {
      dp[j] = (previous[j] + dp[j-1]) % MOD;
      if (j >= i) dp[j] = (dp[j] - previous[j-i] + MOD) % MOD;
    }
  }

  return dp[k];
};

