  for (const c of s) {
    if (c == '*') {
      i3 = 9 * i0 + 9 * i1 + 6 * i2;
      i1 = i0;
      i2 = i0;
    } else {
      i3 = (c > '0') * i0 + i1 + (c <= '6') * i2;
      i1 = (c == '1') * i0;
      i2 = (c == '2') * i0;
