  let low = 1;
  let high = m * n;

  while (low < high) {
    const middle = Math.floor((low + high) / 2);
    if (helper(middle) < k) {
      low = middle + 1;
    } else {
      high = middle;
    }
  }

  return low;

  function helper(x) {
    let count = 0;
    for (let i = 1; i <= m; i++) {
