 * @param {ArrayReader} reader
 * @param {number} target
 * @return {number}
 */
var search = function(reader, target) {
  let left = 0;
  let right = 1;

  while (reader.get(right) < target) {
    left = right;
    right *= 2;
  }

  while (left <= right) {
    const mid = Math.floor((left + right) / 2);
    const value = reader.get(mid);

    if (value === target) {
      return mid;
    } else if (value < target) {
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }

  return -1;
};

