/**
 * @param {_Node} head
 * @param {number} insertVal
 * @return {_Node}
 */
var insert = function(head, insertVal) {
  const newNode = new _Node(insertVal, null);

  if (!head) {
    newNode.next = newNode;
    return newNode;
  }

  if (head.next === head) {
    newNode.next = head;
    head.next = newNode;
    return head;
  }

  let prev = head;
  let curr = head.next;
  do {
    if ((prev.val <= insertVal && insertVal <= curr.val)
        || (prev.val > curr.val && (insertVal >= prev.val || insertVal <= curr.val))) {
      break;
    }
    prev = curr;
    curr = curr.next;
  } while (prev !== head);

  prev.next = newNode;
  newNode.next = curr;

  return head;
};

