  this.mapping = new Map();
  blacklist = new Set(blacklist);

  let last = n - 1;
  for (const b of blacklist) {
    if (b < this.size) {
      while (blacklist.has(last)) last--;
      this.mapping.set(b, last--);
    }
  }
};

