/**
 * @param {number[][]} grid
 * @return {number}
 */
var numDistinctIslands2 = function(grid) {
  const rows = grid.length;
  const cols = grid[0].length;
  const visited = Array.from({ length: rows }, () => new Array(cols).fill(false));
  const uniqueShapes = new Set();

  for (let i = 0; i < rows; i++) {
    for (let j = 0; j < cols; j++) {
      if (grid[i][j] === 1 && !visited[i][j]) {
        const cells = [];
        dfs(i, j, cells);
        const canonical = normalize(cells);
        uniqueShapes.add(canonical);
      }
    }
  }

  return uniqueShapes.size;

  function dfs(row, col, cells) {
    if (row < 0 || row >= rows || col < 0 || col >= cols
        || visited[row][col] || grid[row][col] === 0) {
      return;
    }

    visited[row][col] = true;
    cells.push([row, col]);

    dfs(row + 1, col, cells);
    dfs(row - 1, col, cells);
    dfs(row, col + 1, cells);
    dfs(row, col - 1, cells);
  }

  function normalize(cells) {
    const transformations = [
      (r, c) => [r, c],
      (r, c) => [r, -c],
      (r, c) => [-r, c],
      (r, c) => [-r, -c],
      (r, c) => [c, r],
      (r, c) => [c, -r],
      (r, c) => [-c, r],
      (r, c) => [-c, -r]
    ];

    const shapes = [];

    for (const transform of transformations) {
      const transformed = cells.map(([r, c]) => transform(r, c));
      transformed.sort((a, b) => a[0] === b[0] ? a[1] - b[1] : a[0] - b[0]);

      const minR = transformed[0][0];
      const minC = transformed[0][1];
      const normalized = transformed.map(([r, c]) => [r - minR, c - minC]);

      shapes.push(normalized.map(([r, c]) => `${r},${c}`).join('|'));
    }

    return shapes.sort()[0];
  }
};

minimum-ascii-delete-sum-for-two-strings.solution:
/**
 * @param {string} s1
 * @param {string} s2
 * @return {number}
 */
var minimumDeleteSum = function(s1, s2) {
  const dp = new Array(s1.length + 1).fill().map(() => {
    return new Array(s2.length + 1).fill(0);
  });

  for (let i = 1; i <= s1.length; i++) {
    dp[i][0] = dp[i - 1][0] + s1.charCodeAt(i - 1);
  }
  for (let j = 1; j <= s2.length; j++) {
    dp[0][j] = dp[0][j - 1] + s2.charCodeAt(j - 1);
  }

  for (let i = 1; i <= s1.length; i++) {
    for (let j = 1; j <= s2.length; j++) {
      if (s1[i - 1] === s2[j - 1]) {
        dp[i][j] = dp[i - 1][j - 1];
      } else {
        dp[i][j] = Math.min(
          dp[i - 1][j] + s1.charCodeAt(i - 1),
          dp[i][j - 1] + s2.charCodeAt(j - 1)
        );
      }
    }
  }

  return dp[s1.length][s2.length];
};

