/**
 * @param {string[][]} accounts
 * @return {string[][]}
 */
var accountsMerge = function(accounts) {
  const parent = new Map();
  const names = new Map();
  const groups = new Map();

  const find = node => {
    if (!parent.has(node)) parent.set(node, node);
    return parent.get(node) === node ? node : parent.set(node, find(parent.get(node))).get(node);
  };

  for (const [name, ...emails] of accounts) {
    for (const email of emails) {
      names.set(email, name);
      find(email);
      parent.set(find(email), find(emails[0]));
    }
  }

  for (const email of parent.keys()) {
    const root = find(email);
    if (!groups.has(root)) groups.set(root, new Set());
    groups.get(root).add(email);
  }

  return Array.from(groups, ([root, emails]) => [names.get(root), ...[...emails].sort()]);
};

candy-crush.solution:
/**
 * @param {number[][]} board
 * @return {number[][]}
 */
var candyCrush = function(board) {
  const rows = board.length;
  const cols = board[0].length;

  while (markCrushables()) {
    dropCandies();
  }

  return board;

  function markCrushables() {
    let hasCrushables = false;

    for (let row = 0; row < rows; row++) {
      for (let col = 0; col < cols - 2; col++) {
        const candy = Math.abs(board[row][col]);
        if (candy !== 0 && candy === Math.abs(board[row][col + 1])
            && candy === Math.abs(board[row][col + 2])) {
          hasCrushables = true;
          board[row][col] = -candy;
          board[row][col + 1] = -candy;
          board[row][col + 2] = -candy;
        }
      }
    }

    for (let col = 0; col < cols; col++) {
      for (let row = 0; row < rows - 2; row++) {
        const candy = Math.abs(board[row][col]);
        if (candy !== 0 && candy === Math.abs(board[row + 1][col])
            && candy === Math.abs(board[row + 2][col])) {
          hasCrushables = true;
          board[row][col] = -candy;
          board[row + 1][col] = -candy;
          board[row + 2][col] = -candy;
        }
      }
    }

    return hasCrushables;
  }

  function dropCandies() {
    for (let col = 0; col < cols; col++) {
      let bottom = rows - 1;
      for (let row = rows - 1; row >= 0; row--) {
        if (board[row][col] > 0) {
          board[bottom][col] = board[row][col];
          if (bottom !== row) {
            board[row][col] = 0;
          }
          bottom--;
        } else if (board[row][col] < 0) {
          board[row][col] = 0;
        }
      }
    }
  }
};

