class MyCalendar {
  constructor() {
    this.events = [];
  }

  /**
   * @param {number} startTime
   * @param {number} endTime
   * @returns {boolean}
   */
  book(startTime, endTime) {
    const event = [startTime, endTime];
    const index = this.findInsertIndex(startTime);

    if (this.overlapsPrevious(index - 1, startTime) || this.overlapsNext(index, endTime)) {
      return false;
    }

    this.events.splice(index, 0, event);
    return true;
  }

  /**
   * @param {number} startTime
   * @returns {number}
   */
  findInsertIndex(startTime) {
    let left = 0;
    let right = this.events.length;

    while (left < right) {
      const mid = Math.floor((left + right) / 2);
      if (this.events[mid][0] > startTime) {
        right = mid;
      } else {
        left = mid + 1;
      }
    }

    return left;
  }

  /**
   * @param {number} prevIndex
   * @param {number} startTime
   * @returns {boolean}
   */
  overlapsPrevious(prevIndex, startTime) {
    return prevIndex >= 0 && this.events[prevIndex][1] > startTime;
  }

  /**
   * @param {number} nextIndex
   * @param {number} endTime
   * @returns {boolean}
   */
  overlapsNext(nextIndex, endTime) {
    return nextIndex < this.events.length && this.events[nextIndex][0] < endTime;
  }
}

count-different-palindromic-subsequences.solution:
/**
 * @param {string} s
 * @return {number}
 */
var countPalindromicSubsequences = function(s) {
  const MOD = 1e9 + 7;
  const dp = new Array(s.length).fill().map(() => {
    return new Array(s.length).fill(0);
  });

  for (let i = 0; i < s.length; i++) {
    dp[i][i] = 1;
  }

  for (let len = 2; len <= s.length; len++) {
    for (let start = 0; start + len <= s.length; start++) {
      const end = start + len - 1;
      const charStart = s[start];
      const charEnd = s[end];

      if (charStart !== charEnd) {
        dp[start][end] = (dp[start + 1][end] + dp[start][end - 1] - dp[start + 1][end - 1]) % MOD;
      } else {
        let left = start + 1;
        let right = end - 1;

        while (left <= right && s[left] !== charStart) left++;
        while (left <= right && s[right] !== charStart) right--;

        if (left > right) {
          dp[start][end] = (2 * dp[start + 1][end - 1] + 2) % MOD;
        } else if (left === right) {
          dp[start][end] = (2 * dp[start + 1][end - 1] + 1) % MOD;
        } else {
          dp[start][end] = (2 * dp[start + 1][end - 1] - dp[left + 1][right - 1]) % MOD;
        }
      }

      if (dp[start][end] < 0) dp[start][end] += MOD;
    }
  }

  return dp[0][s.length - 1];
};

