var asteroidCollision = function(asteroids) {
  const result = [];

  for (let i = 0; i < asteroids.length; i++) {
    const previous = result[result.length - 1];
    const current = asteroids[i];

    if (!result.length || previous < 0 || current > 0) {
      result.push(current);
    } else if (-current === previous) {
      result.pop();
    } else if (-current > previous) {
      result.pop();
      i--;
    }
  }

