/**
 * @param {number} n
 * @return {number}
 */
var monotoneIncreasingDigits = function(n) {
  const digits = String(n).split('').map(Number);
  let offset = digits.length;

  for (let i = digits.length - 1; i > 0; i--) {
    if (digits[i - 1] > digits[i]) {
      offset = i;
      digits[i - 1]--;
    }
  }

  for (let i = offset; i < digits.length; i++) {
    digits[i] = 9;
  }

  return +digits.join('');
};

