var minCostClimbingStairs = function(cost) {
  let [first, second] = cost;

  for (let index = 2; index < cost.length; index++) {
    const cursor = cost[index] + Math.min(first, second);
    first = second;
    second = cursor;
  }

  return Math.min(first, second);
};

