  const cols = grid[0].length;
  let result = 0;

  for (let row1 = 0; row1 < rows; row1++) {
    for (let row2 = row1 + 1; row2 < rows; row2++) {
      let sharedOnes = 0;
      for (let col = 0; col < cols; col++) {
        if (grid[row1][col] === 1 && grid[row2][col] === 1) {
          sharedOnes++;
        }
      }
