/**
 * @param {string} ip
 * @param {number} n
 * @return {string[]}
 */
var ipToCIDR = function(ip, n) {
  let start = ipToNumber(ip);
  const result = [];

  while (n > 0) {
    let rightmostOneBit = start & (-start);
    if (rightmostOneBit === 0) rightmostOneBit = 4294967296;

    let blockSize = Math.min(rightmostOneBit, n);
    let temp = blockSize;
    while ((temp & (temp - 1)) !== 0) {
      temp = temp & (temp - 1);
    }
    blockSize = temp;

    let prefixLength = 32;
    let mask = blockSize;
    while (mask > 1) {
      mask >>>= 1;
      prefixLength--;
    }

    result.push(`${numberToIp(start)}/${prefixLength}`);

    start += blockSize;
    n -= blockSize;
  }

  return result;

  function ipToNumber(ip) {
    const parts = ip.split('.').map(Number);
    return (parts[0] << 24) + (parts[1] << 16) + (parts[2] << 8) + parts[3];
  }

  function numberToIp(num) {
    return [
      (num >>> 24) & 255,
      (num >>> 16) & 255,
      (num >>> 8) & 255,
      num & 255
    ].join('.');
  }
};

open-the-lock.solution:
/**
 * @param {string[]} deadends
 * @param {string} target
 * @return {number}
 */
var openLock = function(deadends, target) {
  const dead = new Set(deadends);
  const queue = [['0000', 0]];
  const seen = new Set(['0000']);

  if (dead.has('0000')) return -1;
  while (queue.length) {
    const [combo, turns] = queue.shift();
    if (combo === target) return turns;

    for (let i = 0; i < 4; i++) {
      const current = combo[i];
      const up = (parseInt(current) + 1) % 10;
      const down = (parseInt(current) + 9) % 10;

      const nextUp = combo.slice(0, i) + up + combo.slice(i + 1);
      if (!seen.has(nextUp) && !dead.has(nextUp)) {
        queue.push([nextUp, turns + 1]);
        seen.add(nextUp);
      }

      const nextDown = combo.slice(0, i) + down + combo.slice(i + 1);
      if (!seen.has(nextDown) && !dead.has(nextDown)) {
        queue.push([nextDown, turns + 1]);
        seen.add(nextDown);
      }
    }
  }

  return -1;
};

cracking-the-safe.solution:
/**
 * @param {number} n
 * @param {number} k
 * @return {string}
 */
var crackSafe = function(n, k) {
  if (n === 1) return Array.from({ length: k }, (_, i) => i).join('');
  const seen = new Set();
  const targetSize = k ** n;
  let sequence = '0'.repeat(n);

  seen.add(sequence);
  build(sequence);
  return sequence;

  function build(curr) {
    if (seen.size === targetSize) return true;

    const prefix = curr.slice(-n + 1);
    for (let digit = 0; digit < k; digit++) {
      const next = prefix + digit;
      if (!seen.has(next)) {
        seen.add(next);
        sequence += digit;
        if (build(sequence)) return true;
        sequence = sequence.slice(0, -1);
        seen.delete(next);
      }
    }
    return false;
  }
};

