 */
var reachNumber = function(target) {
  const absTarget = Math.abs(target);
  let moves = Math.floor(Math.sqrt(2 * absTarget));

  while (true) {
    const sum = moves * (moves + 1) / 2;
    if (sum >= absTarget && (sum - absTarget) % 2 === 0) return moves;
    moves++;
  }
};

