var reachingPoints = function(sx, sy, tx, ty) {
  while (tx >= sx && ty >= sy) {
    if (tx === sx && ty === sy) {
      return true;
    }

    if (tx > ty) {
      // If we can directly reach sx by making proper subtractions
      if (ty === sy) {
        return (tx - sx) % ty === 0;
      }
      tx %= ty;
    } else {
      // If we can directly reach sy by making proper subtractions
      if (tx === sx) {
        return (ty - sy) % tx === 0;
      }
      ty %= tx;
    }
  }

  return false;
};

