/**
 * @param {number[][]} board
 * @return {number}
 */
var movesToChessboard = function(board) {
  const n = board.length;

  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      if ((board[0][0] ^ board[i][0] ^ board[0][j] ^ board[i][j]) === 1) {
        return -1;
      }
    }
  }

  let rowSum = 0;
  let colSum = 0;
  let rowSwaps = 0;
  let colSwaps = 0;

  for (let i = 0; i < n; i++) {
    rowSum += board[0][i];
    colSum += board[i][0];

    if (board[i][0] === i % 2) rowSwaps++;
    if (board[0][i] === i % 2) colSwaps++;
  }

  if (rowSum !== Math.floor(n / 2) && rowSum !== Math.ceil(n / 2)) return -1;
  if (colSum !== Math.floor(n / 2) && colSum !== Math.ceil(n / 2)) return -1;

  if (n % 2 === 1) {
    if (rowSwaps % 2 === 1) rowSwaps = n - rowSwaps;
    if (colSwaps % 2 === 1) colSwaps = n - colSwaps;
  } else {
    rowSwaps = Math.min(rowSwaps, n - rowSwaps);
    colSwaps = Math.min(colSwaps, n - colSwaps);
  }

  return Math.floor((rowSwaps + colSwaps) / 2);
};

minimum-distance-between-bst-nodes.solution:
/**
 * Definition for a binary tree node.
 * function TreeNode(val, left, right) {
 *     this.val = (val===undefined ? 0 : val)
 *     this.left = (left===undefined ? null : left)
 *     this.right = (right===undefined ? null : right)
 * }
 */
/**
 * @param {TreeNode} root
 * @return {number}
 */
var minDiffInBST = function(root) {
  let result = Infinity;
  let previous = null;

  inorder(root);
  return result;

  function inorder(node) {
    if (!node) return;
    inorder(node.left);
    result = previous === null ? result : Math.min(result, node.val - previous);
    previous = node.val;
    inorder(node.right);
  }
};

