/**
 * @param {number[]} arr
 * @param {number} k
 * @return {number[]}
 */
var kthSmallestPrimeFraction = function(arr, k) {
  const n = arr.length;
  let left = 0;
  let right = 1;

  while (left < right) {
    const mid = (left + right) / 2;
    let count = 0;
    let maxFraction = [0, 1];
    let j = 1;

    for (let i = 0; i < n - 1; i++) {
      while (j < n && arr[i] > mid * arr[j]) {
        j++;
      }

      count += n - j;

      if (j < n && arr[i] * maxFraction[1] > maxFraction[0] * arr[j]) {
        maxFraction = [arr[i], arr[j]];
      }
    }

    if (count === k) {
      return maxFraction;
    } else if (count < k) {
      left = mid;
    } else {
      right = mid;
    }
  }

  return [];
};

