/**
 * @param {number[][]} routes
 * @param {number} source
 * @param {number} target
 * @return {number}
 */
var numBusesToDestination = function(routes, source, target) {
  if (source === target) return 0;

  const stopToBuses = new Map();

  for (let busId = 0; busId < routes.length; busId++) {
    for (const stop of routes[busId]) {
      if (!stopToBuses.has(stop)) {
        stopToBuses.set(stop, []);
      }
      stopToBuses.get(stop).push(busId);
    }
  }
  if (!stopToBuses.has(source) || !stopToBuses.has(target)) return -1;

  const visitedBuses = new Set();
  const visitedStops = new Set([source]);
  const queue = [[source, 0]];

  while (queue.length > 0) {
    const [currentStop, busCount] = queue.shift();
    if (currentStop === target) return busCount;
    for (const busId of stopToBuses.get(currentStop)) {
      if (visitedBuses.has(busId)) continue;
      visitedBuses.add(busId);
      for (const nextStop of routes[busId]) {
        if (visitedStops.has(nextStop)) continue;
        visitedStops.add(nextStop);
        queue.push([nextStop, busCount + 1]);
        if (nextStop === target) return busCount + 1;
      }
    }
  }

  return -1;
};

ambiguous-coordinates.solution:
/**
 * @param {string} s
 * @return {string[]}
 */
var ambiguousCoordinates = function(s) {
  const digits = s.slice(1, s.length - 1);
  const result = [];

  for (let i = 1; i < digits.length; i++) {
    const leftPart = digits.substring(0, i);
    const rightPart = digits.substring(i);

    const validLeftCoords = getValidCoordinates(leftPart);
    const validRightCoords = getValidCoordinates(rightPart);

    for (const left of validLeftCoords) {
      for (const right of validRightCoords) {
        result.push(`(${left}, ${right})`);
      }
    }
  }

  return result;
};

function getValidCoordinates(s) {
  const coords = [];

  if (isValidInteger(s)) {
    coords.push(s);
  }

  for (let i = 1; i < s.length; i++) {
    const integerPart = s.substring(0, i);
    const decimalPart = s.substring(i);

    if (isValidInteger(integerPart) && isValidDecimal(decimalPart)) {
      coords.push(`${integerPart}.${decimalPart}`);
    }
  }

  return coords;
}

function isValidInteger(s) {
  return s === '0' || s[0] !== '0';
}

function isValidDecimal(s) {
  return s[s.length - 1] !== '0';
}

