most-profit-assigning-work.solution:
/**
 * @param {number[]} difficulty
 * @param {number[]} profit
 * @param {number[]} worker
 * @return {number}
 */
var maxProfitAssignment = function(difficulty, profit, worker) {
  const jobs = difficulty.map((d, i) => [d, profit[i]]);
  jobs.sort((a, b) => a[0] - b[0]);

  const n = jobs.length;
  const bestProfit = new Array(n);
  let maxProfit = 0;

  for (let i = 0; i < n; i++) {
    maxProfit = Math.max(maxProfit, jobs[i][1]);
    bestProfit[i] = [jobs[i][0], maxProfit];
  }

  return worker.reduce((total, ability) => {
    let left = 0;
    let right = n - 1;

    while (left <= right) {
      const mid = (left + right) >> 1;
      bestProfit[mid][0] <= ability ? left = mid + 1 : right = mid - 1;
    }

    return total + (right >= 0 ? bestProfit[right][1] : 0);
  }, 0);
};

making-a-large-island.solution:
/**
 * @param {number[][]} grid
 * @return {number}
 */
var largestIsland = function(grid) {
  function traverse(tile, grid, i, j) {
    if (i < 0 || j < 0 || i >= grid.length || j >= grid[0].length
        || grid[i][j] === 0 || grid[i][j] === tile) {
      return 0;
    }
    grid[i][j] = tile;
    return 1 + (
      traverse(tile, grid, i + 1, j)
      + traverse(tile, grid, i - 1, j)
      + traverse(tile, grid, i, j + 1)
      + traverse(tile, grid, i, j - 1)
    );
  };

  const map = new Map();
  let tile = 2;
  let result = -1;

  for (let i = 0; i < grid.length; i++) {
    for (let j = 0; j < grid.length; j++) {
      if (grid[i][j] === 1) {
        const value = traverse(tile, grid, i, j);
        map.set(tile, value);
        tile += 1;
        result = Math.max(result, value);
      }
    }
  }

  map.set(0, 0);

  for (let i = 0; i < grid.length; i++) {
    for (let j = 0; j < grid.length; j++) {
      if (!grid[i][j]) {
        const seen = new Set();
        let sum = 0;
        if (i > 0) seen.add(grid[i - 1][j]);
        if (j > 0) seen.add(grid[i][j - 1]);
        if (i < grid.length - 1) seen.add(grid[i + 1][j]);
        if (j < grid.length - 1) seen.add(grid[i][j + 1]);
        seen.forEach(val => sum += map.get(val));
        result = Math.max(result, sum + 1);
      }
    }
  }

  return result;
};

