/**
 * @param {string} s
 * @return {number}
 */
var uniqueLetterString = function(s) {
  const n = s.length;
  const lastPositions = {};
  let result = 0;

  for (let i = 0; i < n; i++) {
    const char = s[i];
    if (!lastPositions[char]) lastPositions[char] = [-1, -1];

    const [prevPrev, prev] = lastPositions[char];
    result += (i - prev) * (prev - prevPrev);
    lastPositions[char] = [prev, i];
  }

  for (const char of Object.keys(lastPositions)) {
    const [prev, pos] = lastPositions[char];
    if (pos >= 0) result += (n - pos) * (pos - prev);
  }

  return result;
};

consecutive-numbers-sum.solution:
/**
 * @param {number} n
 * @return {number}
 */
var consecutiveNumbersSum = function(n) {
  let result = 0;

  for (let k = 1; k < Math.sqrt(2 * n); k++) {
    const numerator = n - (k * (k - 1)) / 2;
    if (numerator % k === 0) {
      const startingNum = numerator / k;
      if (startingNum > 0) {
        result++;
      }
    }
  }

  return result;
};

