new-21-game.solution:
/**
 * @param {number} n
 * @param {number} k
 * @param {number} maxPts
 * @return {number}
 */
var new21Game = function(n, k, maxPts) {
  if (k === 0 || n >= k + maxPts - 1) return 1.0;

  const dp = new Array(n + 1).fill(0);
  dp[0] = 1.0;

  let sum = 1.0;
  for (let i = 1; i <= n; i++) {
    dp[i] = sum / maxPts;
    if (i < k) {
      sum += dp[i];
    }
    if (i >= maxPts) {
      sum -= dp[i - maxPts];
    }
  }

  let result = 0;
  for (let i = k; i <= n; i++) {
    result += dp[i];
  }

  return result;
};

push-dominoes.solution:
/**
 * @param {string} dominoes
 * @return {string}
 */
var pushDominoes = function(dominoes) {
  const forces = new Array(dominoes.length).fill(0);

  let force = 0;
  for (let i = 0; i < dominoes.length; i++) {
    if (dominoes[i] === 'R') {
      force = dominoes.length;
    } else if (dominoes[i] === 'L') {
      force = 0;
    } else {
      force = Math.max(force - 1, 0);
    }
    forces[i] += force;
  }

  force = 0;
  for (let i = dominoes.length - 1; i >= 0; i--) {
    if (dominoes[i] === 'L') {
      force = dominoes.length;
    } else if (dominoes[i] === 'R') {
      force = 0;
    } else {
      force = Math.max(force - 1, 0);
    }
    forces[i] -= force;
  }

  return forces.map(f => {
    if (f > 0) return 'R';
    if (f < 0) return 'L';
    return '.';
  }).join('');
};

similar-string-groups.solution:
/**
 * @param {string[]} strs
 * @return {number}
 */
var numSimilarGroups = function(strs) {
  const parent = Array.from({ length: strs.length }, (_, i) => i);
  const rank = new Array(strs.length).fill(0);

  for (let i = 0; i < strs.length; i++) {
    for (let j = i + 1; j < strs.length; j++) {
      if (areSimilar(strs[i], strs[j])) union(i, j);
    }
  }

  const groups = new Set();
  for (let i = 0; i < strs.length; i++) groups.add(find(i));

  return groups.size;

  function find(x) {
    if (parent[x] !== x) {
      parent[x] = find(parent[x]);
    }
    return parent[x];
  }

  function union(x, y) {
    const rootX = find(x);
    const rootY = find(y);

    if (rootX === rootY) return;

    if (rank[rootX] < rank[rootY]) {
      parent[rootX] = rootY;
    } else {
      parent[rootY] = rootX;
      if (rank[rootX] === rank[rootY]) rank[rootX]++;
    }
  }

  function areSimilar(a, b) {
    if (a === b) return true;

    let diff = 0;
    for (let i = 0; i < a.length; i++) {
      if (a[i] !== b[i] && ++diff > 2) return false;
    }

    return diff === 2;
  }
};

magic-squares-in-grid.solution:
/**
 * @param {number[][]} grid
 * @return {number}
 */
var numMagicSquaresInside = function(grid) {
  const rows = grid.length;
  const cols = grid[0].length;

  if (rows < 3 || cols < 3) return 0;

  let result = 0;
  for (let r = 0; r <= rows - 3; r++) {
    for (let c = 0; c <= cols - 3; c++) {
      if (isMagicSquare(grid, r, c)) result++;
    }
  }

  return result;
};

function isMagicSquare(grid, r, c) {
  if (grid[r + 1][c + 1] !== 5) return false;

  const cells = [
    grid[r][c], grid[r][c + 1], grid[r][c + 2],
    grid[r + 1][c], grid[r + 1][c + 1], grid[r + 1][c + 2],
    grid[r + 2][c], grid[r + 2][c + 1], grid[r + 2][c + 2]
  ];

  if (!cells.every(val => val >= 1 && val <= 9) || new Set(cells).size !== 9) return false;

  return (
    grid[r][c] + grid[r][c + 1] + grid[r][c + 2] === 15
    && grid[r + 1][c] + grid[r + 1][c + 1] + grid[r + 1][c + 2] === 15
    && grid[r + 2][c] + grid[r + 2][c + 1] + grid[r + 2][c + 2] === 15
    && grid[r][c] + grid[r + 1][c] + grid[r + 2][c] === 15
    && grid[r][c + 1] + grid[r + 1][c + 1] + grid[r + 2][c + 1] === 15
    && grid[r][c + 2] + grid[r + 1][c + 2] + grid[r + 2][c + 2] === 15
    && grid[r][c] + grid[r + 1][c + 1] + grid[r + 2][c + 2] === 15
    && grid[r][c + 2] + grid[r + 1][c + 1] + grid[r + 2][c] === 15
  );
}

