split-array-into-fibonacci-sequence.solution:
/**
 * @param {string} num
 * @return {number[]}
 */
var splitIntoFibonacci = function(num) {
  const result = [];
  const MAX_INT = 2 ** 31 - 1;
  backtrack(0);
  return result;

  function backtrack(index) {
    if (index === num.length && result.length >= 3) return true;
    for (let length = 1; length <= num.length - index; length++) {
      if (num[index] === '0' && length > 1) break;
      const current = parseInt(num.substring(index, index + length));
      if (current > MAX_INT) break;
      if (result.length >= 2) {
        const sum = result[result.length - 1] + result[result.length - 2];
        if (current > sum) break;
        if (current < sum) continue;
      }
      result.push(current);
      if (backtrack(index + length)) return true;
      result.pop();
    }
    return false;
  }
};

guess-the-word.solution:
/**
 * @param {string[]} words
 * @param {Master} master
 * @return {void}
 */
var findSecretWord = function(words, master) {
  for (let attempt = 0; attempt < 30; attempt++) {
    const randomWord = words[Math.floor(Math.random() * words.length)];
    const matchCount = master.guess(randomWord);

    if (matchCount === 6) return;

    words = words.filter(word =>
      matchCount === -1
        ? countMatches(word, randomWord) === 0
        : countMatches(word, randomWord) === matchCount
    );
  }

  function countMatches(word1, word2) {
    let matches = 0;
    for (let i = 0; i < word1.length; i++) {
      if (word1[i] === word2[i]) matches++;
    }
    return matches;
  }
};

