var backspaceCompare = function(s, t) {
  return handleBackspaces(s) === handleBackspaces(t);
};

function handleBackspaces(input) {
  return input.split('').reduce((result, char) => {
    if (char === '#') {
      result.pop();
    } else {
      result.push(char);
    }
    return result;
  }, []).join('');
}

longest-mountain-in-array.solution:
/**
 * @param {number[]} arr
 * @return {number}
 */
var longestMountain = function(arr) {
  const n = arr.length;
  if (n < 3) return 0;

  let maxLength = 0;
  let i = 1;

  while (i < n - 1) {
    const isPeak = arr[i] > arr[i - 1] && arr[i] > arr[i + 1];
    if (!isPeak) {
      i++;
      continue;
    }
    let leftBound = i - 1;
    while (leftBound > 0 && arr[leftBound - 1] < arr[leftBound]) {
      leftBound--;
    }
    let rightBound = i + 1;
    while (rightBound < n - 1 && arr[rightBound] > arr[rightBound + 1]) {
      rightBound++;
    }
    const mountainLength = rightBound - leftBound + 1;
    maxLength = Math.max(maxLength, mountainLength);
    i = rightBound + 1;
  }

  return maxLength;
};

hand-of-straights.solution:
/**
 * @param {number[]} hand
 * @param {number} groupSize
 * @return {boolean}
 */
var isNStraightHand = function(hand, groupSize) {
  if (hand.length % groupSize) {
    return false;
  }

  const map = {};
  const set = new Set(hand);
  hand.forEach(x => map[x] ? map[x]++ : map[x] = 1);

  let count = hand.length / groupSize;
  while (count--) {
    let min = Math.min(...set);
    for (let i = min; i < min + groupSize; i++) {
      if (!map[i]) {
        return false;
      }
      if (!--map[i]) {
        set.delete(i);
      }
    }
  }

  return true;
};

shortest-path-visiting-all-nodes.solution:
/**
 * @param {number[][]} graph
 * @return {number}
 */
var shortestPathLength = function(graph) {
  const n = graph.length;

  if (n === 1) return 0;

  const allVisited = (1 << n) - 1;
  const queue = [];
  const visited = new Set();

  for (let i = 0; i < n; i++) {
    const initialState = (1 << i);
    queue.push([i, initialState, 0]);
    visited.add(`${i},${initialState}`);
  }

  while (queue.length > 0) {
    const [node, state, distance] = queue.shift();
    if (state === allVisited) {
      return distance;
    }
    for (const neighbor of graph[node]) {
      const newState = state | (1 << neighbor);
      const key = `${neighbor},${newState}`;
      if (!visited.has(key)) {
        visited.add(key);
        queue.push([neighbor, newState, distance + 1]);
      }
    }
  }

  return -1;
};

shifting-letters.solution:
/**
 * @param {string} s
 * @param {number[]} shifts
 * @return {string}
 */
var shiftingLetters = function(s, shifts) {
  const cumulativeShifts = new Array(s.length).fill(0);

  cumulativeShifts[s.length - 1] = shifts[s.length - 1] % 26;
  for (let i = s.length - 2; i >= 0; i--) {
    cumulativeShifts[i] = (cumulativeShifts[i + 1] + shifts[i]) % 26;
  }

  let result = '';
  for (let i = 0; i < s.length; i++) {
    const charCode = s.charCodeAt(i);
    const shiftedCode = ((charCode - 97 + cumulativeShifts[i]) % 26) + 97;
    result += String.fromCharCode(shiftedCode);
  }

  return result;
};

