/**
 * @param {number} target
 * @param {number[]} position
 * @param {number[]} speed
 * @return {number}
 */
var carFleet = function(target, position, speed) {
  const cars = position.map((pos, i) => ({
    position: pos,
    timeToTarget: (target - pos) / speed[i]
  }));
  cars.sort((a, b) => b.position - a.position);

  let slowestTime = 0;
  let result = 0;
  for (const car of cars) {
    if (car.timeToTarget > slowestTime) {
      result++;
      slowestTime = car.timeToTarget;
    }
  }

  return result;
};

k-similar-strings.solution:
/**
 * @param {string} s1
 * @param {string} s2
 * @return {number}
 */
var kSimilarity = function(s1, s2) {
  if (s1 === s2) return 0;
  const queue = [s1];
  const visited = new Set([s1]);
  let swaps = 0;

  while (queue.length) {
    const size = queue.length;
    for (let i = 0; i < size; i++) {
      const current = queue.shift();
      if (current === s2) return swaps;
      let j = 0;
      while (j < current.length && current[j] === s2[j]) j++;
      for (let k = j + 1; k < current.length; k++) {
        if (current[k] === s2[j] && current[k] !== s2[k]) {
          const nextStr = swap(current, j, k);

          if (!visited.has(nextStr)) {
            if (nextStr === s2) return swaps + 1;
            visited.add(nextStr);
            queue.push(nextStr);
          }
        }
      }
    }
    swaps++;
  }

  return swaps;
};

function swap(str, i, j) {
  const chars = str.split('');
  [chars[i], chars[j]] = [chars[j], chars[i]];
  return chars.join('');
}

exam-room.solution:
/**
 * @param {number} n - Number of seats in the exam room
 */
var ExamRoom = function(n) {
  this.n = n;
  this.seats = [];
};

/**
 * @return {number}
 */
ExamRoom.prototype.seat = function() {
  if (this.seats.length === 0) {
    this.seats.push(0);
    return 0;
  }

  let maxDistance = this.seats[0];
  let chosenSeat = 0;

  for (let i = 1; i < this.seats.length; i++) {
    const distance = Math.floor((this.seats[i] - this.seats[i-1]) / 2);
    if (distance > maxDistance) {
      maxDistance = distance;
      chosenSeat = Math.floor((this.seats[i] + this.seats[i-1]) / 2);
    }
  }

  const endDistance = this.n - 1 - this.seats[this.seats.length - 1];
  if (endDistance > maxDistance) {
    chosenSeat = this.n - 1;
    maxDistance = endDistance;
  }

  const insertPosition = this.findInsertPosition(chosenSeat);
  this.seats.splice(insertPosition, 0, chosenSeat);

  return chosenSeat;
};

/**
 * @param {number} p
 * @return {void}
 */
ExamRoom.prototype.leave = function(p) {
  const index = this.seats.indexOf(p);
  this.seats.splice(index, 1);
};

/**
 * @param {number} seat
 * @return {number}
 */
ExamRoom.prototype.findInsertPosition = function(seat) {
  let left = 0;
  let right = this.seats.length - 1;

  while (left <= right) {
    const mid = Math.floor((left + right) / 2);
    if (this.seats[mid] < seat) {
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }

  return left;
};

