/**
 * @param {number[][]} grid
 * @return {number}
 */
var matrixScore = function(grid) {
  const rows = grid.length;
  const cols = grid[0].length;

  for (let row = 0; row < rows; row++) {
    if (grid[row][0] === 0) {
      for (let col = 0; col < cols; col++) {
        grid[row][col] ^= 1;
      }
    }
  }

  let result = rows * (1 << (cols - 1));

  for (let col = 1; col < cols; col++) {
    let onesCount = 0;
    for (let row = 0; row < rows; row++) {
      onesCount += grid[row][col];
    }
    const maxOnes = Math.max(onesCount, rows - onesCount);
    result += maxOnes * (1 << (cols - 1 - col));
  }

  return result;
};

shortest-subarray-with-sum-at-least-k.solution:
/**
 * @param {number[]} nums
 * @param {number} k
 * @return {number}
 */
var shortestSubarray = function(nums, k) {
  const prefixSums = [0];
  for (let i = 0; i < nums.length; i++) {
    prefixSums.push(prefixSums[i] + nums[i]);
  }

  const deque = [];
  let shortestLength = Infinity;

  for (let i = 0; i < prefixSums.length; i++) {
    while (deque.length && prefixSums[i] - prefixSums[deque[0]] >= k) {
      shortestLength = Math.min(shortestLength, i - deque.shift());
    }
    while (deque.length && prefixSums[i] <= prefixSums[deque[deque.length - 1]]) {
      deque.pop();
    }
    deque.push(i);
  }

  return shortestLength === Infinity ? -1 : shortestLength;
};

all-nodes-distance-k-in-binary-tree.solution:
/**
 * Definition for a binary tree node.
 * function TreeNode(val) {
 *     this.val = val;
 *     this.left = this.right = null;
 * }
 */
/**
 * @param {TreeNode} root
 * @param {TreeNode} target
 * @param {number} k
 * @return {number[]}
 */
var distanceK = function(root, target, k) {
  const graph = new Map();
  const result = [];

  buildGraph(root, null);
  findNodesAtDistance(target.val, 0, new Set());

  return result;

  function buildGraph(node, parent) {
    if (!node) return;
    if (parent) {
      graph.set(node.val, graph.get(node.val) || new Set());
      graph.get(node.val).add(parent.val);
      graph.set(parent.val, graph.get(parent.val) || new Set());
      graph.get(parent.val).add(node.val);
    }
    buildGraph(node.left, node);
    buildGraph(node.right, node);
  }

  function findNodesAtDistance(currentVal, distance, visited) {
    if (distance === k) {
      result.push(currentVal);
      return;
    }
    visited.add(currentVal);
    const neighbors = graph.get(currentVal) || new Set();
    for (const neighbor of neighbors) {
      if (!visited.has(neighbor)) {
        findNodesAtDistance(neighbor, distance + 1, visited);
      }
    }
  }
};

shortest-path-to-get-all-keys.solution:
/**
 * @param {string[]} grid
 * @return {number}
 */
var shortestPathAllKeys = function(grid) {
  const rows = grid.length;
  const cols = grid[0].length;
  let startRow;
  let startCol;
  let totalKeys = 0;

  for (let i = 0; i < rows; i++) {
    for (let j = 0; j < cols; j++) {
      if (grid[i][j] === '@') {
        startRow = i;
        startCol = j;
      } else if (/[a-f]/.test(grid[i][j])) {
        totalKeys++;
      }
    }
  }

  const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]];
  const queue = [[startRow, startCol, 0, 0]];
  const visited = new Set([`${startRow},${startCol},0`]);

  while (queue.length) {
    const [row, col, keys, steps] = queue.shift();
    if (keys === (1 << totalKeys) - 1) return steps;
    for (const [dr, dc] of directions) {
      const newRow = row + dr;
      const newCol = col + dc;

      if (newRow >= 0 && newRow < rows && newCol >= 0
          && newCol < cols && grid[newRow][newCol] !== '#') {
        const cell = grid[newRow][newCol];
        const newKeys = /[a-f]/.test(cell)
          ? keys | (1 << (cell.charCodeAt(0) - 97))
          : keys;

        if (/[A-F]/.test(cell) && !(keys & (1 << (cell.charCodeAt(0) - 65)))) continue;
        const state = `${newRow},${newCol},${newKeys}`;
        if (!visited.has(state)) {
          visited.add(state);
          queue.push([newRow, newCol, newKeys, steps + 1]);
        }
      }
    }
  }

  return -1;
};

