  const dp = [startFuel];
  const stationCount = stations.length;

  for (let i = 0; i < stationCount; i++) {
    dp.push(0);
    for (let stops = i; stops >= 0; stops--) {
      if (dp[stops] >= stations[i][0]) {
        dp[stops + 1] = Math.max(dp[stops + 1], dp[stops] + stations[i][1]);
