var decodeAtIndex = function(s, k) {
  let tapeLength = 0;
  let i = 0;

  while (tapeLength < k) {
    if (isLetter(s[i])) {
      tapeLength++;
    } else {
      tapeLength *= parseInt(s[i]);
    }
    i++;
  }

  while (i--) {
    if (isLetter(s[i])) {
      if (tapeLength === k) return s[i];
      tapeLength--;
    } else {
      tapeLength = Math.floor(tapeLength / parseInt(s[i]));
      k = k % tapeLength || tapeLength;
    }
  }
};

