  while (result.length < total) {
    for (let i = 0; i < 2; i++) {
      const [dr, dc] = directions[direction];
      for (let j = 0; j < step; j++) {
        row += dr;
        col += dc;
        if (row >= 0 && row < rows && col >= 0 && col < cols) {
          result.push([row, col]);
        }
      }
      direction = (direction + 1) % 4;
    }
    step++;
  }

  return result;
};

