/**
 * @param {number} n
 * @param {number[][]} dislikes
 * @return {boolean}
 */
var possibleBipartition = function(n, dislikes) {
  const graph = Array.from({ length: n + 1 }, () => []);
  dislikes.forEach(([a, b]) => {
    graph[a].push(b);
    graph[b].push(a);
  });

  const colors = new Array(n + 1).fill(0);

  function colorGraph(person, color) {
    colors[person] = color;
    for (const neighbor of graph[person]) {
      if (colors[neighbor] === color) return false;
      if (colors[neighbor] === 0 && !colorGraph(neighbor, -color)) return false;
    }
    return true;
  }

  for (let person = 1; person <= n; person++) {
    if (colors[person] === 0 && !colorGraph(person, 1)) return false;
  }

  return true;
};

super-egg-drop.solution:
/**
 * @param {number} k
 * @param {number} n
 * @return {number}
 */
var superEggDrop = function(k, n) {
  const dp = new Array(k + 1).fill().map(() => new Array(n + 1).fill(0));

  function solve(eggs, floors) {
    if (floors === 0 || floors === 1) return floors;
    if (eggs === 1) return floors;
    if (dp[eggs][floors]) return dp[eggs][floors];

    let minMoves = floors;
    let low = 1;
    let high = floors;

    while (low <= high) {
      const middle = Math.floor((low + high) / 2);
      const breakCase = solve(eggs - 1, middle - 1);
      const noBreakCase = solve(eggs, floors - middle);
      const moves = 1 + Math.max(breakCase, noBreakCase);

      minMoves = Math.min(minMoves, moves);
      if (breakCase < noBreakCase) low = middle + 1;
      else high = middle - 1;
    }

    dp[eggs][floors] = minMoves;
    return minMoves;
  }

  return solve(k, n);
};

