var sumSubseqWidths = function(nums) {
  const MOD = 1e9 + 7;
  const n = nums.length;
  const powers = [1];

  nums.sort((a, b) => a - b);
  for (let i = 1; i < n; i++) {
    powers[i] = (powers[i - 1] * 2) % MOD;
  }

  let result = 0;
  for (let i = 0; i < n; i++) {
    const contribution = (nums[i] * (powers[i] - powers[n - 1 - i] + MOD)) % MOD;
    result = (result + contribution) % MOD;
  }

  return result;
};

