/**
 * @param {number[][]} graph
 * @param {number[]} initial
 * @return {number}
 */
var minMalwareSpread = function(graph, initial) {
  const n = graph.length;
  const parent = new Array(n).fill().map((_, i) => i);
  const size = new Array(n).fill(1);

  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      if (graph[i][j] === 1) {
        union(i, j);
      }
    }
  }

  let maxSize = 0;
  let result = Math.min(...initial);

  for (const node of initial) {
    const root = find(node);
    let componentInfected = 0;

    for (const infectedNode of initial) {
      if (find(infectedNode) === root) {
        componentInfected++;
      }
    }

    if (componentInfected === 1 && size[root] > maxSize) {
      maxSize = size[root];
      result = node;
    } else if (componentInfected === 1 && size[root] === maxSize) {
      result = Math.min(result, node);
    }
  }

  return result;

  function find(x) {
    if (parent[x] !== x) {
      parent[x] = find(parent[x]);
    }
    return parent[x];
  }

  function union(x, y) {
    const rootX = find(x);
    const rootY = find(y);
    if (rootX !== rootY) {
      parent[rootX] = rootY;
      size[rootY] += size[rootX];
    }
  }
};

