/**
 * @param {number[]} arr
 * @return {number[]}
 */
var threeEqualParts = function(arr) {
  const totalOnes = arr.reduce((sum, num) => sum + num, 0);
  if (totalOnes % 3 !== 0) {
    return [-1, -1];
  }
  if (totalOnes === 0) {
    return [0, arr.length - 1];
  }

  const onesPerPart = totalOnes / 3;
  let firstStart = -1;
  let secondStart = -1;
  let thirdStart = -1;
  let onesCount = 0;
  for (let i = 0; i < arr.length; i++) {
    if (arr[i] === 1) {
      onesCount++;
      if (onesCount === 1) firstStart = i;
      if (onesCount === onesPerPart + 1) secondStart = i;
      if (onesCount === 2 * onesPerPart + 1) thirdStart = i;
    }
  }

  const patternLength = arr.length - thirdStart;
  if (secondStart - firstStart < patternLength || thirdStart - secondStart < patternLength) {
    return [-1, -1];
  }
  for (let i = 0; i < patternLength; i++) {
    if (arr[firstStart + i] !== arr[secondStart + i]
        || arr[firstStart + i] !== arr[thirdStart + i]) {
      return [-1, -1];
    }
  }

  const i = firstStart + patternLength - 1;
  const j = secondStart + patternLength;

  return [i, j];
};

minimize-malware-spread-ii.solution:
/**
 * @param {number[][]} graph
 * @param {number[]} initial
 * @return {number}
 */
var minMalwareSpread = function(graph, initial) {
  const n = graph.length;
  const initialSet = new Set(initial);

  initial.sort((a, b) => a - b);

  const infected = new Set(initial);
  const queue = [...initial];

  for (let i = 0; i < queue.length; i++) {
    const node = queue[i];
    for (let neighbor = 0; neighbor < n; neighbor++) {
      if (graph[node][neighbor] === 1 && !infected.has(neighbor)) {
        infected.add(neighbor);
        queue.push(neighbor);
      }
    }
  }

  const sourcesMap = new Array(n).fill().map(() => []);

  for (const initialNode of initial) {
    const reachable = new Set();
    const visited = new Set(initial);
    visited.delete(initialNode);

    const q = [initialNode];
    while (q.length > 0) {
      const node = q.shift();
      reachable.add(node);

      for (let neighbor = 0; neighbor < n; neighbor++) {
        if (graph[node][neighbor] === 1 && !visited.has(neighbor)) {
          visited.add(neighbor);
          q.push(neighbor);
        }
      }
    }

    for (let node = 0; node < n; node++) {
      if (reachable.has(node) && !initialSet.has(node)) {
        sourcesMap[node].push(initialNode);
      }
    }
  }

  const savedCounts = new Map();
  for (let node = 0; node < n; node++) {
    if (sourcesMap[node].length === 1) {
      const source = sourcesMap[node][0];
      savedCounts.set(source, (savedCounts.get(source) || 0) + 1);
    }
  }

  let maxSaved = 0;
  let result = initial[0];

  for (const node of initial) {
    const saved = savedCounts.get(node) || 0;
    if (saved > maxSaved) {
      maxSaved = saved;
      result = node;
    } else if (saved === maxSaved && node < result) {
      result = node;
    }
  }

  return result;
};

