/**
 * @param {number[]} tokens
 * @param {number} power
 * @return {number}
 */
var bagOfTokensScore = function(tokens, power) {
  let score = 0;
  let result = 0;
  let left = 0;
  let right = tokens.length - 1;

  tokens.sort((a, b) => a - b);

  while (left <= right && (power >= tokens[left] || score > 0)) {
    while (left <= right && power >= tokens[left]) {
      power -= tokens[left];
      score++;
      left++;
    }
    result = Math.max(result, score);

    if (left <= right && score > 0) {
      power += tokens[right];
      score--;
      right--;
    }
  }

  return result;
};

