/**
 * @param {TreeNode} root
 * @return {number}
 */
var minCameraCover = function(root) {
  let cameras = 0;
  const rootState = traverse(root);
  return rootState === 0 ? cameras + 1 : cameras;

  function traverse(node) {
    if (!node) return 1;

    const left = traverse(node.left);
    const right = traverse(node.right);

    if (left === 0 || right === 0) {
      cameras++;
      return 2;
