var clumsy = function(n) {
  if (n <= 2) return n;
  if (n === 3) return 6;

  let result = Math.floor(n * (n - 1) / (n - 2)) + (n - 3);
  n -= 4;

  while (n >= 4) {
    result -= Math.floor(n * (n - 1) / (n - 2)) - (n - 3);
    n -= 4;
  }

  if (n === 3) result -= 6;
  else if (n === 2) result -= 2;
  else if (n === 1) result -= 1;

  return result;
};

