 */
var maxAncestorDiff = function(root) {
  return traverse(root, root.val, root.val);

  function traverse(node, maxVal, minVal) {
    if (!node) return maxVal - minVal;

    maxVal = Math.max(maxVal, node.val);
    minVal = Math.min(minVal, node.val);

