/**
 * @param {number[][]} grid
 * @param {number} row
 * @param {number} col
 * @param {number} color
 * @return {number[][]}
 */
var colorBorder = function(grid, row, col, color) {
  const rows = grid.length;
  const cols = grid[0].length;
  const visited = new Set();
  const originalColor = grid[row][col];
  const borders = new Set();

  function findBorders(r, c) {
    if (r < 0 || r >= rows || c < 0 || c >= cols
        || visited.has(`${r},${c}`) || grid[r][c] !== originalColor) {
      return;
    }

    visited.add(`${r},${c}`);

    if (r === 0 || r === rows - 1 || c === 0 || c === cols - 1
        || (r > 0 && grid[r - 1][c] !== originalColor)
        || (r < rows - 1 && grid[r + 1][c] !== originalColor)
        || (c > 0 && grid[r][c - 1] !== originalColor)
        || (c < cols - 1 && grid[r][c + 1] !== originalColor)) {
      borders.add(`${r},${c}`);
    }

    findBorders(r - 1, c);
    findBorders(r + 1, c);
    findBorders(r, c - 1);
    findBorders(r, c + 1);
  }

  findBorders(row, col);
  borders.forEach(pos => {
    const [r, c] = pos.split(',').map(Number);
    grid[r][c] = color;
  });

  return grid;
};

