  const m = nums1.length;
  const n = nums2.length;

  const dp = new Array(m + 1).fill().map(() => new Array(n + 1).fill(0));

  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      if (nums1[i - 1] === nums2[j - 1]) {
        dp[i][j] = dp[i - 1][j - 1] + 1;
      } else {
        dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);
      }
    }
  }

  return dp[m][n];
};

escape-a-large-maze.solution:
/**
 * @param {number[][]} blocked
 * @param {number[]} source
 * @param {number[]} target
 * @return {boolean}
 */
var isEscapePossible = function(blocked, source, target) {
  const MAX = 1e6;
  const LIMIT = 19900;
  const blockedSet = new Set(blocked.map(([x, y]) => `${x},${y}`));

  if (!helper(source, target)) {
    return false;
  }

  return helper(target, source);

  function helper(start, goal) {
    const queue = [start];
    const visited = new Set([`${start[0]},${start[1]}`]);
    const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]];

    while (queue.length && visited.size <= LIMIT) {
      const [x, y] = queue.shift();

      for (const [dx, dy] of directions) {
        const newX = x + dx;
        const newY = y + dy;
        const key = `${newX},${newY}`;

        if (newX < 0 || newX >= MAX || newY < 0 || newY >= MAX
            || blockedSet.has(key) || visited.has(key)) {
          continue;
        }

        if (newX === goal[0] && newY === goal[1]) {
          return true;
        }

        queue.push([newX, newY]);
        visited.add(key);
      }
    }

    return visited.size > LIMIT;
  }
};

