/**
 * @param {number[]} arr
 * @param {number} k
 * @return {number}
 */
var maxSumAfterPartitioning = function(arr, k) {
  const dp = new Array(arr.length + 1).fill(0);

  for (let i = 1; i <= arr.length; i++) {
    let maxVal = 0;
    for (let j = 1; j <= Math.min(k, i); j++) {
      maxVal = Math.max(maxVal, arr[i - j]);
      dp[i] = Math.max(dp[i], dp[i - j] + maxVal * j);
    }
  }

  return dp[arr.length];
};

longest-duplicate-substring.solution:
/**
 * @param {string} s
 * @return {string}
 */
var longestDupSubstring = function(s) {
  const MOD = 1e9 + 7;
  const BASE = 26;
  let left = 1;
  let right = s.length - 1;
  let result = '';

  while (left <= right) {
    const mid = Math.floor((left + right) / 2);
    const candidate = checkLength(mid);
    if (candidate) {
      result = candidate;
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }

  return result;

  function checkLength(len) {
    let hash = 0;
    const seen = new Map();
    let basePow = 1;
    for (let i = 0; i < len - 1; i++) {
      basePow = (basePow * BASE) % MOD;
    }

    for (let i = 0; i < len; i++) {
      hash = (hash * BASE + (s.charCodeAt(i) - 97)) % MOD;
    }

    seen.set(hash, [0]);

    for (let i = 1; i <= s.length - len; i++) {
      hash = (hash - ((s.charCodeAt(i - 1) - 97) * basePow) % MOD + MOD) % MOD;
      hash = (hash * BASE + (s.charCodeAt(i + len - 1) - 97)) % MOD;
      if (seen.has(hash)) {
        const prevIndices = seen.get(hash);
        const currSubstr = s.slice(i, i + len);
        for (const prev of prevIndices) {
          if (s.slice(prev, prev + len) === currSubstr) {
            return currSubstr;
          }
        }
        prevIndices.push(i);
      } else {
        seen.set(hash, [i]);
      }
    }
    return '';
  }
};

