var lastStoneWeight = function(stones) {
  const heap = stones.sort((a, b) => b - a);

  while (heap.length > 1) {
    const heaviest = heap.shift();
    const secondHeaviest = heap.shift();
    if (heaviest !== secondHeaviest) {
      heap.push(heaviest - secondHeaviest);
      heap.sort((a, b) => b - a);
