  let swapIndex = -1;

  for (let i = arr.length - 2; i >= 0; i--) {
    if (arr[i] > arr[i + 1]) {
      swapIndex = i;
      break;
    }
  }

  if (swapIndex === -1) return arr;

  let maxLessIndex = swapIndex + 1;
  for (let j = swapIndex + 2; j < arr.length; j++) {
    if (arr[j] < arr[swapIndex] && arr[j] > arr[maxLessIndex]) {
