/**
 * @param {number[]} arr1
 * @param {number[]} arr2
 * @return {number[]}
 */
var addNegabinary = function(arr1, arr2) {
  const result = [];
  let i = arr1.length - 1;
  let j = arr2.length - 1;
  let carry = 0;

  while (i >= 0 || j >= 0 || carry !== 0) {
    const x = i >= 0 ? arr1[i--] : 0;
    const y = j >= 0 ? arr2[j--] : 0;
    const sum = x + y + carry;

    result.unshift(sum & 1);
    carry = sum >= 2 ? -1 : sum < 0 ? 1 : 0;
  }

  while (result.length > 1 && result[0] === 0) {
    result.shift();
  }

  return result;
};

