/**
 * @param {string} str1
 * @param {string} str2
 * @return {string}
 */
var shortestCommonSupersequence = function(str1, str2) {
  const dp = new Array(str1.length + 1).fill().map(() => new Array(str2.length + 1).fill(0));
  let result = '';

  for (let i = 0; i <= str1.length; i++) {
    dp[i][0] = i;
  }
  for (let j = 0; j <= str2.length; j++) {
    dp[0][j] = j;
  }

  for (let i = 1; i <= str1.length; i++) {
    for (let j = 1; j <= str2.length; j++) {
      dp[i][j] = str1[i-1] === str2[j-1] ? dp[i-1][j-1] + 1 : Math.min(dp[i-1][j], dp[i][j-1]) + 1;
    }
  }

  for (let i = str1.length, j = str2.length; i > 0 || j > 0;) {
    if (!i) {
      result = str2[--j] + result;
    } else if (!j) {
      result = str1[--i] + result;
    } else if (str1[i-1] === str2[j-1]) {
      result = str1[--i] + (str2[--j], result);
    } else {
      dp[i][j] === dp[i-1][j] + 1
        ? result = str1[--i] + result
        : result = str2[--j] + result;
    }
  }

  return result;
};

statistics-from-a-large-sample.solution:
/**
 * @param {number[]} count
 * @return {number[]}
 */
var sampleStats = function(count) {
  let minimum = 256;
  let maximum = -1;
  let sum = 0;
  let totalCount = 0;
  let mode = 0;
  let maxFrequency = 0;

  for (let value = 0; value < 256; value++) {
    const frequency = count[value];
    if (frequency > 0) {
      minimum = Math.min(minimum, value);
      maximum = Math.max(maximum, value);
      sum += value * frequency;
      totalCount += frequency;
      if (frequency > maxFrequency) {
        maxFrequency = frequency;
        mode = value;
      }
    }
  }

  const mean = sum / totalCount;
  const median = findMedian(count, totalCount);

  return [minimum, maximum, mean, median, mode];
};

function findMedian(count, totalCount) {
  const isOdd = totalCount % 2 === 1;
  const target = Math.floor(totalCount / 2);
  let currentCount = 0;
  let firstMedian = -1;

  for (let value = 0; value < 256; value++) {
    currentCount += count[value];
    if (isOdd) {
      if (currentCount > target) return value;
    } else {
      if (firstMedian === -1 && currentCount >= target) {
        firstMedian = value;
      }
      if (currentCount > target) {
        return (firstMedian + value) / 2;
      }
    }
  }
}

