/**
 * @param {number} target
 * @param {MountainArray} mountainArr
 * @return {number}
 */
var findInMountainArray = function(target, mountainArr) {
  const length = mountainArr.length();

  let left = 0;
  let right = length - 1;
  while (left < right) {
    const mid = Math.floor((left + right) / 2);
    if (mountainArr.get(mid) < mountainArr.get(mid + 1)) {
      left = mid + 1;
    } else {
      right = mid;
    }
  }
  const peak = left;

  left = 0;
  right = peak;
  while (left <= right) {
    const mid = Math.floor((left + right) / 2);
    const value = mountainArr.get(mid);
    if (value === target) return mid;
    if (value < target) {
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }

  left = peak;
  right = length - 1;
  while (left <= right) {
    const mid = Math.floor((left + right) / 2);
    const value = mountainArr.get(mid);
    if (value === target) return mid;
    if (value > target) {
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }

  return -1;
};

brace-expansion-ii.solution:
/**
 * @param {string} expression
 * @return {string[]}
 */
var braceExpansionII = function(expression) {
  function cartesian(set1, set2) {
    const result = new Set();
    for (const a of set1) {
      for (const b of set2) {
        result.add(a + b);
      }
    }
    return result;
  }

  function evaluate(exp) {
    let i = 0;

    function parseUnit() {
      let result = new Set();

      if (exp[i] === '{') {
        i++;
        result = parseExprList();
        i++;
      } else {
        result.add(exp[i]);
        i++;
      }

      return result;
    }

    function parseExprList() {
      const result = new Set();

      const firstExpr = parseExpr();
      for (const word of firstExpr) {
        result.add(word);
      }

      while (i < exp.length && exp[i] === ',') {
        i++;
        const nextExpr = parseExpr();
        for (const word of nextExpr) {
          result.add(word);
        }
      }

      return result;
    }

    function parseExpr() {
      let result = new Set(['']);

      while (i < exp.length && exp[i] !== ',' && exp[i] !== '}') {
        const unit = parseUnit();
        result = cartesian(result, unit);
      }

      return result;
    }

    return parseExprList();
  }

  return [...evaluate(expression)].sort();
};

