  nums.sort((a, b) => a - b);
  let left = 0;
  let right = nums.length - 1;
  let result = -1;

  while (left < right) {
    const sum = nums[left] + nums[right];

    if (sum < k) {
      result = Math.max(result, sum);
      left++;
    } else {
      right--;
    }
  }

  return result;
};

