connecting-cities-with-minimum-cost.solution:
/**
 * @param {number} n
 * @param {number[][]} connections
 * @return {number}
 */
var minimumCost = function(n, connections) {
  const parent = Array.from({ length: n + 1 }, (_, i) => i);

  connections.sort((a, b) => a[2] - b[2]);

  let totalCost = 0;
  let edgesUsed = 0;

  for (const [city1, city2, cost] of connections) {
    if (union(city1, city2)) {
      totalCost += cost;
      edgesUsed++;

      if (edgesUsed === n - 1) {
        return totalCost;
      }
    }
  }

  return -1;

  function findParent(x) {
    if (parent[x] !== x) {
      parent[x] = findParent(parent[x]);
    }
    return parent[x];
  }

  function union(x, y) {
    const rootX = findParent(x);
    const rootY = findParent(y);

    if (rootX !== rootY) {
      parent[rootX] = rootY;
      return true;
    }
    return false;
  }
};

parallel-courses.solution:
/**
 * @param {number} n
 * @param {number[][]} relations
 * @return {number}
 */
var minimumSemesters = function(n, relations) {
  const graph = new Map();
  const indegree = new Array(n + 1).fill(0);

  for (let i = 1; i <= n; i++) {
    graph.set(i, []);
  }

  for (const [prev, next] of relations) {
    graph.get(prev).push(next);
    indegree[next]++;
  }

  const queue = [];
  for (let i = 1; i <= n; i++) {
    if (indegree[i] === 0) {
      queue.push(i);
    }
  }

  let semesters = 0;
  let coursesCompleted = 0;

  while (queue.length > 0) {
    const currentSemesterSize = queue.length;
    semesters++;

    for (let i = 0; i < currentSemesterSize; i++) {
      const course = queue.shift();
      coursesCompleted++;

      for (const nextCourse of graph.get(course)) {
        indegree[nextCourse]--;
        if (indegree[nextCourse] === 0) {
          queue.push(nextCourse);
        }
      }
    }
  }

  return coursesCompleted === n ? semesters : -1;
};

