/**
 * @param {number[][]} grid
 * @return {number}
 */
var largest1BorderedSquare = function(grid) {
  const rows = grid.length;
  const cols = grid[0].length;
  const left = Array(rows).fill().map(() => Array(cols).fill(0));
  const top = Array(rows).fill().map(() => Array(cols).fill(0));
  let maxSide = 0;

  for (let i = 0; i < rows; i++) {
    for (let j = 0; j < cols; j++) {
      if (grid[i][j]) {
        left[i][j] = j > 0 ? left[i][j - 1] + 1 : 1;
        top[i][j] = i > 0 ? top[i - 1][j] + 1 : 1;

        let side = Math.min(left[i][j], top[i][j]);
        while (side > maxSide) {
          if (left[i - side + 1][j] >= side && top[i][j - side + 1] >= side) {
            maxSide = side;
            break;
          }
          side--;
        }
      }
    }
  }

  return maxSide * maxSide;
};

stone-game-ii.solution:
/**
 * @param {number[]} piles
 * @return {number}
 */
var stoneGameII = function(piles) {
  const n = piles.length;
  const cache = new Map();
  const suffixSums = new Array(n + 1).fill(0);

  for (let i = n - 1; i >= 0; i--) {
    suffixSums[i] = suffixSums[i + 1] + piles[i];
  }

  return maxStones(0, 1);

  function maxStones(index, m) {
    if (index >= n) return 0;
    if (2 * m >= n - index) return suffixSums[index];

    const key = `${index},${m}`;
    if (cache.has(key)) return cache.get(key);

    let opponentMin = Infinity;
    for (let x = 1; x <= 2 * m; x++) {
      opponentMin = Math.min(opponentMin, maxStones(index + x, Math.max(m, x)));
    }

    const result = suffixSums[index] - opponentMin;
    cache.set(key, result);
    return result;
  }
};

