/**
 * @param {number[]} nums
 * @return {number}
 */
var movesToMakeZigzag = function(nums) {
  function calculateMoves(peakEven) {
    let moves = 0;
    const adjusted = [...nums];

    for (let i = 0; i < adjusted.length; i++) {
      if ((i % 2 === 0) === peakEven) {
        const left = i > 0 ? adjusted[i - 1] : Infinity;
        const right = i < adjusted.length - 1 ? adjusted[i + 1] : Infinity;
        const target = Math.min(left, right) - 1;
        if (adjusted[i] >= target) {
          moves += adjusted[i] - target;
          adjusted[i] = target;
        }
      }
    }

    return moves;
  }

  const evenPeaks = calculateMoves(true);
  const oddPeaks = calculateMoves(false);

  return Math.min(evenPeaks, oddPeaks);
};

binary-tree-coloring-game.solution:
/**
 * Definition for a binary tree node.
 * function TreeNode(val, left, right) {
 *     this.val = (val===undefined ? 0 : val)
 *     this.left = (left===undefined ? null : left)
 *     this.right = (right===undefined ? null : right)
 * }
 */
/**
 * @param {TreeNode} root
 * @param {number} n
 * @param {number} x
 * @return {boolean}
 */
var btreeGameWinningMove = function(root, n, x) {
  let leftCount = 0;
  let rightCount = 0;

  countNodes(root);

  const parentCount = n - leftCount - rightCount - 1;
  const maxRegion = Math.max(parentCount, leftCount, rightCount);

  return maxRegion > n / 2;

  function countNodes(node) {
    if (!node) return 0;
    const left = countNodes(node.left);
    const right = countNodes(node.right);
    if (node.val === x) {
      leftCount = left;
      rightCount = right;
    }
    return left + right + 1;
  }
};

