/**
 * @param {string} text
 * @return {number}
 */
var longestDecomposition = function(text) {
  return decompose(0, text.length - 1);

  function decompose(start, end) {
    if (start > end) return 0;
    if (start === end) return 1;

    const left = start;
    const right = end;
    let chunkSize = 0;

    while (left + chunkSize < right - chunkSize) {
      chunkSize++;
      if (text.slice(left, left + chunkSize) === text.slice(right - chunkSize + 1, right + 1)) {
        return 2 + decompose(left + chunkSize, right - chunkSize);
      }
    }

    return 1;
  }
};

check-if-a-number-is-majority-element-in.solution:
/**
 * @param {number[]} nums
 * @param {number} target
 * @return {boolean}
 */
var isMajorityElement = function(nums, target) {
  const firstIndex = findFirstIndex(target);
  if (firstIndex >= nums.length || nums[firstIndex] !== target) {
    return false;
  }

  const lastIndex = findLastIndex(target);
  const frequency = lastIndex - firstIndex + 1;

  return frequency > nums.length / 2;

  function findFirstIndex(target) {
    let left = 0;
    let right = nums.length;
    while (left < right) {
      const mid = Math.floor((left + right) / 2);
      if (nums[mid] < target) {
        left = mid + 1;
      } else {
        right = mid;
      }
    }
    return left;
  }

  function findLastIndex(target) {
    let left = 0;
    let right = nums.length;
    while (left < right) {
      const mid = Math.floor((left + right) / 2);
      if (nums[mid] <= target) {
        left = mid + 1;
      } else {
        right = mid;
      }
    }
    return left - 1;
  }
};

minimum-swaps-to-group-all-1s-together.solution:
/**
 * @param {number[]} data
 * @return {number}
 */
var minSwaps = function(data) {
  const totalOnes = data.reduce((sum, val) => sum + val, 0);

  if (totalOnes <= 1) return 0;

  let currentOnes = 0;
  for (let i = 0; i < totalOnes; i++) {
    currentOnes += data[i];
  }

  let maxOnes = currentOnes;

  for (let i = totalOnes; i < data.length; i++) {
    currentOnes = currentOnes - data[i - totalOnes] + data[i];
    maxOnes = Math.max(maxOnes, currentOnes);
  }

  return totalOnes - maxOnes;
};

