/**
 * @param {string} text
 * @return {number}
 */
var maxRepOpt1 = function(text) {
  const map = new Map();
  for (const char of text) {
    map.set(char, (map.get(char) || 0) + 1);
  }

  let result = 0;
  for (let i = 0; i < text.length;) {
    const currentChar = text[i];
    const segmentStart = i;

    while (i < text.length && text[i] === currentChar) i++;
    const segmentLength = i - segmentStart;

    const totalAvailable = map.get(currentChar);
    if (i < text.length && segmentLength < totalAvailable) {
      const nextStart = i + 1;
      let nextLength = 0;
      while (nextStart + nextLength < text.length && text[nextStart + nextLength] === currentChar) {
        nextLength++;
      }
      result = Math.max(result, Math.min(segmentLength + nextLength + 1, totalAvailable));
    }
    result = Math.max(result, Math.min(
      segmentLength + (totalAvailable > segmentLength ? 1 : 0), totalAvailable
    ));
  }

  return result;
};

online-majority-element-in-subarray.solution:
/**
 * @param {number[]} arr
 */
var MajorityChecker = function(arr) {
  this.positionMap = new Map();
  this.array = arr;
  for (let i = 0; i < arr.length; i++) {
    const positions = this.positionMap.get(arr[i]) || [];
    positions.push(i);
    this.positionMap.set(arr[i], positions);
  }
};

/**
 * @param {number} left
 * @param {number} right
 * @param {number} threshold
 * @return {number}
 */
MajorityChecker.prototype.query = function(left, right, threshold) {
  const maxAttempts = 20;
  const rangeLength = right - left + 1;

  for (let attempt = 0; attempt < maxAttempts; attempt++) {
    const candidate = this.array[left + Math.floor(Math.random() * rangeLength)];
    const positions = this.positionMap.get(candidate);
    const count = countInRange(positions, left, right);

    if (count >= threshold) return candidate;
    if (count + rangeLength - count < threshold) return -1;
  }
  return -1;
};

function countInRange(positions, left, right) {
  const leftIndex = lowerBound(positions, left);
  const rightIndex = upperBound(positions, right);
  return rightIndex - leftIndex;
}

function lowerBound(arr, target) {
  let start = 0;
  let end = arr.length;
  while (start < end) {
    const mid = Math.floor((start + end) / 2);
    if (arr[mid] < target) start = mid + 1;
    else end = mid;
  }
  return start;
}

function upperBound(arr, target) {
  let start = 0;
  let end = arr.length;
  while (start < end) {
    const mid = Math.floor((start + end) / 2);
    if (arr[mid] <= target) start = mid + 1;
    else end = mid;
  }
  return start;
}

