  let windowSum = 0;
  let points = 0;

  for (let i = 0; i < k; i++) {
    windowSum += calories[i];
  }

  if (windowSum < lower) points--;
  else if (windowSum > upper) points++;

  for (let i = k; i < calories.length; i++) {
