  const MOD = 1e9 + 7;
  const arraySum = arr.reduce((sum, num) => sum + num, 0);
  const maxSingle = helper(arr);

  if (k === 1) return maxSingle;

  const doubleArray = [...arr, ...arr];
  const maxDouble = helper(doubleArray);

