/**
 * @param {number[]} arr
 * @return {number[]}
 */
var transformArray = function(arr) {
  let current = [...arr];

  while (true) {
    const next = [...current];
    let changed = false;

    for (let i = 1; i < current.length - 1; i++) {
      if (current[i] < current[i - 1] && current[i] < current[i + 1]) {
        next[i]++;
        changed = true;
      } else if (current[i] > current[i - 1] && current[i] > current[i + 1]) {
        next[i]--;
        changed = true;
      }
    }

    if (!changed) break;
    current = next;
  }

  return current;
};

