  let xyCount = 0;
  let yxCount = 0;

  for (let i = 0; i < s1.length; i++) {
    if (s1[i] === 'x' && s2[i] === 'y') xyCount++;
    if (s1[i] === 'y' && s2[i] === 'x') yxCount++;
