/**
 * @param {number} upper
 * @param {number} lower
 * @param {number[]} colsum
 * @return {number[][]}
 */
var reconstructMatrix = function(upper, lower, colsum) {
  const n = colsum.length;
  const matrix = [[], []];
  let upperLeft = upper;
  let lowerLeft = lower;

  for (let i = 0; i < n; i++) {
    if (colsum[i] === 2) {
      matrix[0][i] = 1;
      matrix[1][i] = 1;
      upperLeft--;
      lowerLeft--;
    } else {
      matrix[0][i] = 0;
      matrix[1][i] = 0;
    }
  }

  if (upperLeft < 0 || lowerLeft < 0) return [];

  for (let i = 0; i < n; i++) {
    if (colsum[i] === 1) {
      if (upperLeft > 0) {
        matrix[0][i] = 1;
        matrix[1][i] = 0;
        upperLeft--;
      } else if (lowerLeft > 0) {
        matrix[0][i] = 0;
        matrix[1][i] = 1;
        lowerLeft--;
      } else {
        return [];
      }
    }
  }

  return upperLeft === 0 && lowerLeft === 0 ? matrix : [];
};

