/**
 * @param {number[]} nums
 * @param {number} threshold
 * @return {number}
 */
var smallestDivisor = function(nums, threshold) {
  let left = 1;
  let right = Math.max(...nums);

  while (left < right) {
    const mid = Math.floor((left + right) / 2);
    const sum = nums.reduce((acc, num) => acc + Math.ceil(num / mid), 0);

    if (sum <= threshold) {
      right = mid;
    } else {
      left = mid + 1;
    }
  }

  return left;
};

minimum-number-of-flips-to-convert-binar.solution:
/**
 * @param {number[][]} mat
 * @return {number}
 */
var minFlips = function(mat) {
  const rows = mat.length;
  const cols = mat[0].length;
  const target = 0;
  const start = mat.flat().reduce((acc, val, idx) => acc | (val << idx), 0);
  const queue = [[start, 0]];
  const seen = new Set([start]);
  const directions = [[0, 0], [0, 1], [0, -1], [1, 0], [-1, 0]];

  while (queue.length) {
    const [state, steps] = queue.shift();

    if (state === target) return steps;

    for (let i = 0; i < rows; i++) {
      for (let j = 0; j < cols; j++) {
        let nextState = state;
        for (const [di, dj] of directions) {
          const ni = i + di;
          const nj = j + dj;
          if (ni >= 0 && ni < rows && nj >= 0 && nj < cols) {
            const pos = ni * cols + nj;
            nextState ^= (1 << pos);
          }
        }
        if (!seen.has(nextState)) {
          seen.add(nextState);
          queue.push([nextState, steps + 1]);
        }
      }
    }
  }

  return -1;
};

