    queue = nextQueue;
    currentLevel++;
  }

  const videoFrequency = new Map();
  queue.forEach(person => watchedVideos[person].forEach(video => {
    return videoFrequency.set(video, (videoFrequency.get(video) || 0) + 1);
  }));

  return [...videoFrequency.entries()]
