/**
 * @param {number} n
 * @param {number[][]} connections
 * @return {number}
 */
var makeConnected = function(n, connections) {
  const parent = Array(n).fill(-1);
  let isNotConnected = n - 1;
  let count = 0;

  connections.forEach(([node, connection]) => {
    if (search(node) !== search(connection)) {
      const p1 = search(node);
      const p2 = search(connection);
      if (p1 !== p2) {
        parent[p2] = p1;
      }
      isNotConnected--;
    } else {
      count++;
    }
  });

  return isNotConnected <= count ? isNotConnected : -1;

  function search(node) {
    if (parent[node] === -1) {
      return node;
    }
    parent[node] = search(parent[node]);
    return parent[node];
  }
};

minimum-distance-to-type-a-word-using-tw.solution:
/**
 * @param {string} word
 * @return {number}
 */
var minimumDistance = function(word) {
  const memo = {};
  return dp(0, null, null);

  function dp(index, finger1, finger2) {
    if (index === word.length) return 0;

    const key = `${index},${finger1},${finger2}`;
    if (memo[key] !== undefined) return memo[key];

    const nextChar = word[index];
    const moveFinger1 = distance(finger1, nextChar) + dp(index + 1, nextChar, finger2);
    const moveFinger2 = distance(finger2, nextChar) + dp(index + 1, finger1, nextChar);

    memo[key] = Math.min(moveFinger1, moveFinger2);
    return memo[key];
  }

  function getPosition(char) {
    const code = char.charCodeAt(0) - 65;
    return [Math.floor(code / 6), code % 6];
  }

  function distance(from, to) {
    if (from === null) return 0;
    const [x1, y1] = getPosition(from);
    const [x2, y2] = getPosition(to);
    return Math.abs(x1 - x2) + Math.abs(y1 - y2);
  }
};

