var longestDiverseString = function(a, b, c) {
  const counts = [
    { char: 'a', count: a },
    { char: 'b', count: b },
    { char: 'c', count: c }
  ];
  const result = [];

  while (true) {
    counts.sort((x, y) => y.count - x.count);

    let added = false;
    for (let i = 0; i < 3; i++) {
      const { char, count } = counts[i];
      if (count === 0) continue;

      const total = result.length;
      if (total >= 2 && result[total - 1] === char && result[total - 2] === char) {
        continue;
      }

      result.push(char);
      counts[i].count--;
      added = true;
      break;
    }

    if (!added) break;
  }

  return result.join('');
};

