  while (fibonacci[fibonacci.length - 1] <= k) {
    fibonacci.push(fibonacci[fibonacci.length - 1] + fibonacci[fibonacci.length - 2]);
  }

  let count = 0;
  let remaining = k;

  for (let i = fibonacci.length - 1; i >= 0 && remaining > 0; i--) {
