    if (isNaN(char)) {
      letters.push(char);
    } else {
      digits.push(char);
    }
  }
  if (Math.abs(letters.length - digits.length) > 1) {
    return '';
  }
  const result = [];
  const longer = letters.length >= digits.length ? letters : digits;
  const shorter = longer === letters ? digits : letters;
  for (let i = 0; i < longer.length; i++) {
