  const maxSums = [...nums];
  const deque = [];
  let result = nums[0];

  for (let i = 0; i < nums.length; i++) {
    while (deque.length && deque[0] < i - k) {
      deque.shift();
    }

    if (deque.length) {
      maxSums[i] = Math.max(maxSums[i], maxSums[deque[0]] + nums[i]);
    }

    while (deque.length && maxSums[deque[deque.length - 1]] <= maxSums[i]) {
      deque.pop();
    }

