var minReorder = function(n, connections) {
  const graph = new Array(n).fill(null).map(() => []);

  connections.forEach(([k, v]) => {
    graph[k].push([v, 1]);
    graph[v].push([k, 0]);
  });

  function dfs(node, parent) {
    let count = 0;

    graph[node].forEach(([k, v]) => {
      if (k !== parent) {
