  houses.sort((a, b) => a - b);
  const n = houses.length;
  const cache = new Map();

  return findMinDistance(0, k);

  function medianDistance(start, end) {
    let sum = 0;
    const mid = Math.floor((start + end) / 2);
    for (let i = start; i <= end; i++) {
      sum += Math.abs(houses[i] - houses[mid]);
    }
    return sum;
