var numSubmat = function(mat) {
  const rows = mat.length;
  const cols = mat[0].length;
  const heights = new Array(cols).fill(0);
  let result = 0;

  for (let i = 0; i < rows; i++) {
    const stack = [];
    for (let j = 0; j < cols; j++) {
      heights[j] = mat[i][j] === 1 ? heights[j] + 1 : 0;

      while (stack.length && heights[j] <= heights[stack[stack.length - 1]]) {
        stack.pop();
      }

      stack.push(j);

      for (let k = 0; k < stack.length; k++) {
        const height = heights[stack[k]];
        const width = k === 0 ? stack[k] + 1 : stack[k] - stack[k - 1];
        result += height * width;
      }
    }
  }

  return result;
};

minimum-possible-integer-after-at-most-k.solution:
/**
 * @param {string} num
 * @param {number} k
 * @return {string}
 */
var minInteger = function(num, k) {
  const digits = num.split('');
  const n = digits.length;
  const fenwick = new Array(n + 1).fill(0);
  const digitQueues = Array.from({ length: 10 }, () => []);
  const result = [];

  for (let i = 0; i < n; i++) {
    digitQueues[digits[i]].push(i);
  }

  for (let i = 0; i < n; i++) {
    for (let digit = 0; digit <= 9; digit++) {
      if (digitQueues[digit].length === 0) continue;
      const pos = digitQueues[digit][0];
      const swapsNeeded = pos - fetchValue(pos);
      if (swapsNeeded <= k) {
        k -= swapsNeeded;
        result.push(digit);
        update(pos);
        digitQueues[digit].shift();
        break;
      }
    }
  }

  return result.join('');

  function update(index) {
    for (let i = index + 1; i <= n; i += i & -i) {
      fenwick[i]++;
    }
  }

  function fetchValue(index) {
    let sum = 0;
    for (let i = index + 1; i > 0; i -= i & -i) {
      sum += fenwick[i];
    }
    return sum;
  }
};

