/**
 * @param {number[][]} positions
 * @return {number}
 */
var getMinDistSum = function(positions) {
  const n = positions.length;
  let xSum = 0;
  let ySum = 0;

  for (const [x, y] of positions) {
    xSum += x;
    ySum += y;
  }

  let xCenter = xSum / n;
  let yCenter = ySum / n;
  const epsilon = 1e-7;
  const maxIterations = 1000;

  for (let iter = 0; iter < maxIterations; iter++) {
    let xNumerator = 0;
    let yNumerator = 0;
    let denominator = 0;

    for (const [x, y] of positions) {
      const dx = xCenter - x;
      const dy = yCenter - y;
      const dist = Math.sqrt(dx * dx + dy * dy);
      if (dist < epsilon) continue;
      const weight = 1 / dist;
      xNumerator += x * weight;
      yNumerator += y * weight;
      denominator += weight;
    }

    if (denominator < epsilon) break;

    const newX = xNumerator / denominator;
    const newY = yNumerator / denominator;

    if (Math.abs(newX - xCenter) < epsilon && Math.abs(newY - yCenter) < epsilon) {
      break;
    }

    xCenter = newX;
    yCenter = newY;
  }

  let sumDist = 0;
  for (const [x, y] of positions) {
    sumDist += Math.sqrt((xCenter - x) ** 2 + (yCenter - y) ** 2);
  }

  return sumDist;
};

move-sub-tree-of-n-ary-tree.solution:
/**
 * // Definition for a Node.
 * function Node(val, children) {
 *    this.val = val === undefined ? 0 : val;
 *    this.children = children === undefined ? [] : children;
 * };
 */

/**
 * @param {Node} root
 * @param {Node} p
 * @param {Node} q
 * @return {Node}
 */
var moveSubTree = function(root, p, q) {
  if (q.children.includes(p)) return root;

  const pParent = findParent(root, p);
  const qParent = findParent(root, q);

  if (isDescendant(q, p)) {
    qParent.children = qParent.children.filter(child => child !== q);
    q.children.push(p);

    if (!pParent) return q;

    pParent.children[pParent.children.indexOf(p)] = q;
  } else {
    q.children.push(p);
    pParent.children = pParent.children.filter(child => child !== p);
  }

  return root;

  function findParent(node, target) {
    if (!node) return null;
    for (const child of node.children) {
      if (child === target) return node;
      const parent = findParent(child, target);
      if (parent) return parent;
    }
    return null;
  }

  function isDescendant(target, node) {
    if (!node) return false;
    if (node === target) return true;
    return node.children.some(child => isDescendant(target, child));
  }
};

