  const MOD = 1e9 + 7;
  const m = nums1.length;
  const n = nums2.length;
  let i = 0;
  let j = 0;
  let sum1 = 0;
  let sum2 = 0;

  while (i < m && j < n) {
    if (nums1[i] < nums2[j]) {
      sum1 += nums1[i++];
    } else if (nums1[i] > nums2[j]) {
      sum2 += nums2[j++];
    } else {
      sum1 = sum2 = Math.max(sum1, sum2) + nums1[i];
      i++;
      j++;
    }
  }

  while (i < m) {
    sum1 += nums1[i++];
  }

  while (j < n) {
    sum2 += nums2[j++];
  }

  return Math.max(sum1, sum2) % MOD;
};

