  const n = arr.length;
  let left = 0;

  while (left < n - 1 && arr[left] <= arr[left + 1]) {
    left++;
  }

  if (left === n - 1) return 0;

  let right = n - 1;
  while (right > 0 && arr[right - 1] <= arr[right]) {
    right--;
  }

  let minLength = Math.min(n - left - 1, right);

  for (let i = 0, j = right; i <= left && j < n; i++) {
    while (j < n && arr[i] > arr[j]) {
      j++;
    }
