  minCost[0] = 0;

  for (let i = 0; i < n; i++) {
    let minIdx = -1;
    let minVal = Infinity;

    for (let j = 0; j < n; j++) {
      if (!visited.has(j) && minCost[j] < minVal) {
        minVal = minCost[j];
        minIdx = j;
      }
    }

    if (minIdx === -1) break;

    visited.add(minIdx);
    result += minVal;

    for (let j = 0; j < n; j++) {
      if (!visited.has(j)) {
        const cost = Math.abs(points[minIdx][0] - points[j][0])
          + Math.abs(points[minIdx][1] - points[j][1]);
        minCost[j] = Math.min(minCost[j], cost);
      }
    }
  }

  return result;
};

