/**
 * @param {number} n
 * @param {number[][]} edges
 * @return {number[]}
 */
var countSubgraphsForEachDiameter = function(n, connections) {
  const adjacencyList = Array.from({ length: n }, () => []);
  for (const [u, v] of connections) {
    adjacencyList[u - 1].push(v - 1);
    adjacencyList[v - 1].push(u - 1);
  }

  const diameterCounts = new Array(n - 1).fill(0);

  for (let mask = 1; mask < 1 << n; mask++) {
    const selectedNodes = Array(n).fill(0);
    let nodeCount = 0;
    for (let i = 0; i < n; i++) {
      if (mask & (1 << i)) {
        selectedNodes[i] = 1;
        nodeCount++;
      }
    }

    if (nodeCount < 2) continue;

    const start = selectedNodes.findIndex(bit => bit);
    const { maxDist: dist1, farthestNode, distances } = findMaxDistance(selectedNodes, start);

    if (distances.some((d, i) => selectedNodes[i] && d === -1)) continue;

    const { maxDist: dist2 } = findMaxDistance(selectedNodes, farthestNode);

    if (dist2 > 0) {
      diameterCounts[dist2 - 1]++;
    }
  }

  return diameterCounts;

  function findMaxDistance(nodes, start) {
    const distances = new Array(n).fill(-1);
    const queue = [start];
    distances[start] = 0;
    let maxDist = 0;
    let farthestNode = start;

    while (queue.length) {
      const current = queue.shift();
      for (const neighbor of adjacencyList[current]) {
        if (nodes[neighbor] && distances[neighbor] === -1) {
          distances[neighbor] = distances[current] + 1;
          if (distances[neighbor] > maxDist) {
            maxDist = distances[neighbor];
            farthestNode = neighbor;
          }
          queue.push(neighbor);
        }
      }
    }

    return { maxDist, farthestNode, distances };
  }
};

maximum-font-to-fit-a-sentence-in-a-scre.description:
You are given a string text. We want to display text on a screen of width w and height h.
You can choose any font size from array fonts, which contains the available font sizes in
ascending order.
You can use the FontInfo interface to get the width and height of any character at any
available font size.
The FontInfo interface is defined as such:
interface FontInfo {
// Returns the width of character ch on the screen using font size fontSize.
// O(1) per call
public int getWidth(int fontSize, char ch);
// Returns the height of any character on the screen using font size fontSize.
// O(1) per call
public int getHeight(int fontSize);
}
The calculated width of text for some fontSize is the sum of every
getWidth(fontSize, text[i]) call for each 0 <= i < text.length (0-indexed).
The calculated height of text for some fontSize is getHeight(fontSize). Note
that text is displayed on a single line.
It is guaranteed that FontInfo will return the same value if you call getHeight
or getWidth with the same parameters.
It is also guaranteed that for any font size fontSize and any character ch:
- getHeight(fontSize) <= getHeight(fontSize+1)
- getWidth(fontSize, ch) <= getWidth(fontSize+1, ch)
Return the maximum font size you can use to display text on the screen. If text cannot
fit on the display with any font size, return -1.

