/**
 * @param {number[]} destination
 * @param {number} k
 * @return {string}
 */
var kthSmallestPath = function(destination, k) {
  let verticalMoves = destination[0];
  let horizontalMoves = destination[1];
  const totalMoves = verticalMoves + horizontalMoves;
  let path = '';

  for (let i = 0; i < totalMoves; i++) {
    if (horizontalMoves === 0) {
      path += 'V';
      verticalMoves--;
      continue;
    }
    const combinations = calculateCombinations(
      verticalMoves + horizontalMoves - 1,
      horizontalMoves - 1
    );
    if (k <= combinations) {
      path += 'H';
      horizontalMoves--;
    } else {
      path += 'V';
      verticalMoves--;
      k -= combinations;
    }
  }

  return path;
};

function calculateCombinations(n, r) {
  if (r < 0 || r > n) return 0;
  let result = 1;
  for (let i = 1; i <= r; i++) {
    result = result * (n - i + 1) / i;
  }
  return Math.floor(result);
}

lowest-common-ancestor-of-a-binary-tree-.solution:
/**
 * Definition for a binary tree node.
 * function TreeNode(val) {
 *     this.val = val;
 *     this.left = this.right = null;
 * }
 */
/**
 * @param {TreeNode} root
 * @param {TreeNode} p
 * @param {TreeNode} q
 * @return {TreeNode}
 */
var lowestCommonAncestor = function(root, p, q) {
  let foundP = false;
  let foundQ = false;

  const lca = findLCA(root);
  return foundP && foundQ ? lca : null;

  function findLCA(node) {
    if (!node) return null;

    const leftResult = findLCA(node.left);
    const rightResult = findLCA(node.right);

    let currentMatch = false;
    if (node === p) {
      foundP = true;
      currentMatch = true;
    }

    if (node === q) {
      foundQ = true;
      currentMatch = true;
    }

    if (leftResult && rightResult) {
      return node;
    }

    if (currentMatch && (leftResult || rightResult)) {
      return node;
    }

    return leftResult || rightResult || (currentMatch ? node : null);
  }
};

