/**
 * @param {number[]} inventory
 * @param {number} orders
 * @return {number}
 */
var maxProfit = function(inventory, orders) {
  const MOD = 1e9 + 7;
  inventory.sort((a, b) => b - a);
  inventory.push(0);

  let totalProfit = 0;
  let currentColor = 0;
  let ballsSold = 0;

  while (ballsSold < orders) {
    const currentCount = inventory[currentColor];
    const nextCount = inventory[currentColor + 1];
    const colors = currentColor + 1;
    const ballsToSell = Math.min(
      orders - ballsSold,
      colors * (currentCount - nextCount)
    );

    const fullSets = Math.floor(ballsToSell / colors);
    const remainder = ballsToSell % colors;

    if (fullSets > 0) {
      const endValue = currentCount - fullSets + 1;
      let sequenceSum = (BigInt(colors) * BigInt(fullSets) % BigInt(MOD))
        * (BigInt(currentCount) + BigInt(endValue)) % BigInt(MOD);
      sequenceSum = (sequenceSum * BigInt(500000004)) % BigInt(MOD);
      totalProfit = (totalProfit + Number(sequenceSum)) % MOD;
    }

    if (remainder > 0) {
      totalProfit = (totalProfit + (remainder * (currentCount - fullSets)) % MOD) % MOD;
    }

    ballsSold += ballsToSell;
    currentColor++;
  }

  return totalProfit;
};

create-sorted-array-through-instructions.solution:
/**
 * @param {number[]} instructions
 * @return {number}
 */
var createSortedArray = function(instructions) {
  const MOD = 1e9 + 7;
  const maxValue = Math.max(...instructions);
  const fenwickTree = new Array(maxValue + 1).fill(0);
  let totalCost = 0;

  for (let i = 0; i < instructions.length; i++) {
    const value = instructions[i];
    const lessCount = query(value - 1);
    const greaterCount = i - query(value);
    totalCost = (totalCost + Math.min(lessCount, greaterCount)) % MOD;
    update(value);
  }

  return totalCost;

  function update(index) {
    for (let i = index; i <= maxValue; i += i & -i) {
      fenwickTree[i]++;
    }
  }

  function query(index) {
    let sum = 0;
    for (let i = index; i > 0; i -= i & -i) {
      sum += fenwickTree[i];
    }
    return sum;
  }
};

lowest-common-ancestor-of-a-binary-tree-.description:
Given two nodes of a binary tree p and q, return their lowest common ancestor (LCA).
Each node will have a reference to its parent node. The definition for Node is below:
class Node {
public int val;
public Node left;
public Node right;
public Node parent;
}
According to the definition of LCA on Wikipedia: "The lowest common ancestor of two
nodes p and q in a tree T is the lowest node that has both p and q as descendants
(where we allow a node to be a descendant of itself)."

lowest-common-ancestor-of-a-binary-tree-.solution:
/**
 * // Definition for a _Node.
 * function _Node(val) {
 *    this.val = val;
 *    this.left = null;
 *    this.right = null;
 *    this.parent = null;
 * };
 */

/**
 * @param {_Node} p
 * @param {_Node} q
 * @return {_Node}
 */
var lowestCommonAncestor = function(p, q) {
  const set = new Set();

  let current = p;
  while (current) {
    set.add(current);
    current = current.parent;
  }

  current = q;
  while (current) {
    if (set.has(current)) {
      return current;
    }
    current = current.parent;
  }

  return null;
};

