  let oddSum = 0;
  let result = 0;

  for (let i = 0; i < nums.length; i++) {
    if (i % 2 === 0) evenSum += nums[i];
    else oddSum += nums[i];
  }

  let currentEven = 0;
  let currentOdd = 0;

  for (let i = 0; i < nums.length; i++) {
    if (i % 2 === 0) {
      evenSum -= nums[i];
      if (currentEven + oddSum === currentOdd + evenSum) result++;
      currentEven += nums[i];
    } else {
      oddSum -= nums[i];
