/**
 * @param {number[]} nums
 * @return {number[]}
 */
var getSumAbsoluteDifferences = function(nums) {
  const n = nums.length;
  const result = new Array(n);
  let prefixSum = 0;
  let suffixSum = nums.reduce((sum, num) => sum + num, 0);

  for (let i = 0; i < n; i++) {
    const current = nums[i];
    suffixSum -= current;
    result[i] = (current * i - prefixSum) + (suffixSum - current * (n - 1 - i));
    prefixSum += current;
  }

  return result;
};

