  const MOD = 1e9 + 7;
  const dp = new Array(n + 1).fill(0).map(() => new Array(k + 1).fill(0));

  for (let i = 1; i <= n; i++) {
    dp[i][1] = 1;
  }

  for (let candies = 2; candies <= n; candies++) {
    for (let bags = 2; bags <= Math.min(candies, k); bags++) {
      dp[candies][bags] = (dp[candies - 1][bags - 1] + (bags * dp[candies - 1][bags]) % MOD) % MOD;
