  const n = grid[0].length;
  const result = new Array(n);

  for (let col = 0; col < n; col++) {
    let currentCol = col;
    let row = 0;

    while (row < m) {
      const nextCol = currentCol + grid[row][currentCol];

      if (nextCol < 0 || nextCol >= n || grid[row][currentCol] !== grid[row][nextCol]) {
        currentCol = -1;
        break;
      }

      currentCol = nextCol;
      row++;
    }

    result[col] = currentCol;
  }

  return result;
};

