/**
 * // This is the GridMaster's API interface.
 * // You should not implement it, or speculate about its implementation
 * function GridMaster() {
 *
 *     @param {character} direction
 *     @return {boolean}
 *     this.canMove = function(direction) {
 *         ...
 *     };
 *     @param {character} direction
 *     @return {void}
 *     this.move = function(direction) {
 *         ...
 *     };
 *     @return {boolean}
 *     this.isTarget = function() {
 *         ...
 *     };
 * };
 */

/**
 * @param {GridMaster} master
 * @return {integer}
 */
var findShortestPath = function(master) {
  const directions = [
    ['U', 'D', 0, -1],
    ['D', 'U', 0, 1],
    ['L', 'R', -1, 0],
    ['R', 'L', 1, 0]
  ];

  const visited = new Set();
  let targetPosition = null;

  dfs(0, 0);

  if (!targetPosition) return -1;

  const queue = [[0, 0, 0]];
  const bfsVisited = new Set(['0,0']);

  while (queue.length > 0) {
    const [x, y, distance] = queue.shift();

    if (x === targetPosition[0] && y === targetPosition[1]) {
      return distance;
    }

    for (const [, , dx, dy] of directions) {
      const newX = x + dx;
      const newY = y + dy;
      const key = `${newX},${newY}`;

      if (!bfsVisited.has(key) && visited.has(key)) {
        bfsVisited.add(key);
        queue.push([newX, newY, distance + 1]);
      }
    }
  }

  return -1;

  function dfs(x, y) {
    const key = `${x},${y}`;
    if (visited.has(key)) return;
    visited.add(key);

    if (master.isTarget()) {
      targetPosition = [x, y];
      return;
    }

    for (const [moveDir, backDir, dx, dy] of directions) {
      if (master.canMove(moveDir)) {
        master.move(moveDir);
        dfs(x + dx, y + dy);
        master.move(backDir);
      }
    }
  }
};

