/**
 * @param {number} n
 * @param {number} index
 * @param {number} maxSum
 * @return {number}
 */
var maxValue = function(n, index, maxSum) {
  function minSumRequired(peak) {
    const leftCount = Math.min(index, peak - 1);
    const rightCount = Math.min(n - index - 1, peak - 1);
    let sum = peak;
    sum += (peak - 1 + peak - leftCount) * leftCount / 2;
    sum += (peak - 1 + peak - rightCount) * rightCount / 2;
    sum += (index - leftCount) + (n - index - 1 - rightCount);
    return sum;
  }

  let low = 1;
  let high = maxSum;
  let result = 1;

  while (low <= high) {
    const mid = Math.floor((low + high) / 2);
    if (minSumRequired(mid) <= maxSum) {
      result = mid;
      low = mid + 1;
    } else {
      high = mid - 1;
    }
  }

  return result;
};

count-pairs-with-xor-in-a-range.solution:
/**
 * @param {number[]} nums
 * @param {number} low
 * @param {number} high
 * @return {number}
 */
var countPairs = function(nums, low, high) {
  const root = new TrieNode();
  let total = 0;

  for (const num of nums) {
    total += countPairsInRange(num, high, root) - countPairsInRange(num, low - 1, root);
    insert(num, root);
  }

  return total;
};

class TrieNode {
  constructor() {
    this.children = [null, null];
    this.count = 0;
  }
}

function countPairsInRange(num, limit, root, depth = 14) {
  let count = 0;
  let node = root;
  for (let i = depth; i >= 0 && node; i--) {
    const numBit = (num >> i) & 1;
    const limitBit = (limit >> i) & 1;
    if (limitBit === 0) {
      node = node.children[numBit];
    } else {
      if (node.children[numBit]) {
        count += node.children[numBit].count;
      }
      node = node.children[numBit ^ 1];
    }
  }
  return count + (node ? node.count : 0);
}

function insert(num, root) {
  let node = root;
  for (let i = 14; i >= 0; i--) {
    const bit = (num >> i) & 1;
    if (!node.children[bit]) {
      node.children[bit] = new TrieNode();
    }
    node = node.children[bit];
    node.count++;
  }
}

