  function gcd(a, b) {
    while (b) [a, b] = [b, a % b];
    return a;
  }

  for (const num of nums) {
    exists[num] = true;
  }

  for (let i = 1; i <= maxNum; i++) {
    let currentGcd = 0;
    for (let j = i; j <= maxNum; j += i) {
      if (exists[j]) {
        currentGcd = currentGcd ? gcd(currentGcd, j) : j;
