 * @return {number[]}
 */
var memLeak = function(memory1, memory2) {
  let time = 1;
  let stick1 = memory1;
  let stick2 = memory2;

  while (time <= stick1 || time <= stick2) {
    if (stick1 >= stick2) {
      if (stick1 < time) break;
      stick1 -= time;
    } else {
      if (stick2 < time) break;
      stick2 -= time;
    }
    time++;
  }

  return [time, stick1, stick2];
};

