var maxLength = function(ribbons, k) {
  let left = 1;
  let right = Math.max(...ribbons);
  let result = 0;

  while (left <= right) {
    const mid = Math.floor((left + right) / 2);

    if (helper(mid)) {
      result = mid;
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }

  return result;

  function helper(length) {
    let count = 0;
    for (const ribbon of ribbons) {
      count += Math.floor(ribbon / length);
      if (count >= k) return true;
    }
    return false;
  }
};

