var maximumRemovals = function(s, p, removable) {
  let left = 0;
  let right = removable.length;

  while (left <= right) {
    const mid = (left + right) >> 1;
    const removed = new Set(removable.slice(0, mid));
    let i = 0;
    let j = 0;

    while (i < s.length && j < p.length) {
      if (!removed.has(i) && s[i] === p[j]) {
        j++;
      }
      i++;
    }

    if (j === p.length) {
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }

  return right;
};

