/**
 * @param {string} s
 * @return {boolean}
 */
var isDecomposable = function(s) {
  const groups = [];
  let i = 0;

  while (i < s.length) {
    let j = i;
    while (j < s.length && s[j] === s[i]) {
      j++;
    }
    groups.push(j - i);
    i = j;
  }

  let result = false;

  for (const length of groups) {
    if (length % 3 === 1) {
      return false;
    } else if (length % 3 === 2) {
      if (result) {
        return false;
      }
      result = true;
    }
  }

  return result;
};

