    events.push([end, -color]);
  }

  events.sort((a, b) => a[0] - b[0] || a[1] - b[1]);

  const result = [];
  let currentSum = 0;
  let prevPoint = events[0][0];

  for (const [point, color] of events) {
    if (currentSum > 0 && point > prevPoint) {
      result.push([prevPoint, point, currentSum]);
    }
    currentSum += color;
    prevPoint = point;
  }

  return result;
};

