/**
 * @param {number} row
 * @param {number} col
 * @param {number[][]} cells
 * @return {number}
 */
var latestDayToCross = function(row, col, cells) {
  const directions = [[-1, 0], [1, 0], [0, -1], [0, 1]];
  let left = 1;
  let right = cells.length;
  let result = 0;

  while (left <= right) {
    const mid = Math.floor((left + right) / 2);
    if (canCross(mid)) {
      result = mid;
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }

  return result;

  function canCross(day) {
    const grid = new Array(row).fill().map(() => new Array(col).fill(0));
    for (let i = 0; i < day; i++) {
      const [r, c] = cells[i];
      grid[r - 1][c - 1] = 1;
    }

    const queue = [];
    const visited = new Array(row).fill().map(() => new Array(col).fill(false));

    for (let c = 0; c < col; c++) {
      if (grid[0][c] === 0) {
        queue.push([0, c]);
        visited[0][c] = true;
      }
    }

    while (queue.length) {
      const [r, c] = queue.shift();
      if (r === row - 1) return true;

      for (const [dr, dc] of directions) {
        const nr = r + dr;
        const nc = c + dc;
        if (nr >= 0 && nr < row && nc >= 0 && nc < col && !visited[nr][nc] && grid[nr][nc] === 0) {
          queue.push([nr, nc]);
          visited[nr][nc] = true;
        }
      }
    }
    return false;
  }
};

