/**
 * @param {number[]} nums
 * @return {number}
 */
var subarraysWithMoreZerosThanOnes = function(nums) {
  const MOD = 1e9 + 7;
  const dp = [0, 0];
  const mp = new Map();
  let sum = 0;
  let answer = 0;

  mp.set(0, 1);

  for (const num of nums) {
    const dpPrev = [...dp];

    if (num === 1) {
      sum++;
    } else {
      sum--;
    }

    dp[0] = mp.get(sum) || 0;

    if (num === 1) {
      dp[1] = (dpPrev[0] + dpPrev[1] + 1) % MOD;
    } else {
      dp[1] = (dpPrev[1] - dp[0] + MOD) % MOD;
    }

    mp.set(sum, (mp.get(sum) || 0) + 1);
    answer = (answer + dp[1]) % MOD;
  }

  return answer;
};

