  let [currPrice, timestamp] = this.maxHeap.dequeue();

  while (currPrice !== this.timestamps.get(timestamp)) {
    [currPrice, timestamp] = this.maxHeap.dequeue();
  }

  this.maxHeap.enqueue([currPrice, timestamp]);
  return currPrice;
};

/**
 * @return {number}
 */
