  if (account1 > this.accounts.length || account2 > this.accounts.length) return false;
  if (this.accounts[account1 - 1] < money) return false;

  this.accounts[account1 - 1] -= money;
  this.accounts[account2 - 1] += money;
  return true;
};

/**
