/**
 * Definition for singly-linked list.
 * function ListNode(val, next) {
 *     this.val = (val===undefined ? 0 : val)
 *     this.next = (next===undefined ? null : next)
 * }
 */
/**
 * @param {ListNode} head
 * @return {ListNode}
 */
var reverseEvenLengthGroups = function(head) {
  let prevGroup = head;
  let groupLength = 2;

  while (prevGroup.next) {
    let count = 0;
    let current = prevGroup.next;
    const groupStart = current;

    while (current && count < groupLength) {
      current = current.next;
      count++;
    }

    if (count % 2 === 0) {
      prevGroup.next = reverseGroup(groupStart, count);
    }

    for (let i = 0; i < count; i++) {
      prevGroup = prevGroup.next;
    }

    groupLength++;
  }

  return head;

  function reverseGroup(start, length) {
    let prev = null;
    let current = start;
    for (let i = 0; i < length; i++) {
      const next = current.next;
      current.next = prev;
      prev = current;
      current = next;
    }
    start.next = current;
    return prev;
  }
};

