  const n = nums.length;
  const cycleLength = 2 * n;

  return queries.map(([time, index]) => {
    const position = time % cycleLength;

    if (position < n) {
      const currentLength = n - position;
      return index < currentLength ? nums[position + index] : -1;
    } else {
