abbreviating-the-product-of-a-range.solution:
/**
 * @param {number} left
 * @param {number} right
 * @return {string}
 */
var abbreviateProduct = function(left, right) {
  let zeros = 0;
  let count2 = 0;
  let count5 = 0;

  for (let i = left; i <= right; i++) {
    let n = i;
    while (n % 2 === 0) {
      count2++;
      n = Math.floor(n / 2);
    }
    n = i;
    while (n % 5 === 0) {
      count5++;
      n = Math.floor(n / 5);
    }
  }
  zeros = Math.min(count2, count5);

  let digits = 0;
  for (let i = left; i <= right; i++) {
    digits += Math.log10(i);
  }
  digits = Math.floor(digits) + 1;

  if (digits - zeros <= 10) {
    let product = 1n;
    for (let i = left; i <= right; i++) {
      product *= BigInt(i);
    }
    for (let i = 0; i < zeros; i++) {
      product /= 10n;
    }
    return product.toString() + 'e' + zeros;
  }

  let prefix = 1;
  for (let i = left; i <= right; i++) {
    prefix *= i;
    while (prefix >= 1e10) {
      prefix /= 10;
    }
  }
  prefix = prefix.toString().slice(0, 5);

  let suffix = 1n;
  for (let i = right; i >= left; i--) {
    suffix = (suffix * BigInt(i));
    while (suffix % 10n === 0n) {
      suffix /= 10n;
    }
    suffix = suffix % (10n ** 15n);
  }

  suffix = suffix.toString();
  while (suffix.length < 5) {
    suffix = '0' + suffix;
  }
  suffix = suffix.slice(-5);

  return prefix + '...' + suffix + 'e' + zeros;
};

