 */
var maximumInvitations = function(fav) {
  const n = fav.length;
  const graph = new Array(n).fill().map(() => []);
  const seen = new Set();
  let result = 0;

  for (let i = 0; i < n; i++) {
    graph[fav[i]].push(i);
  }

  for (let i = 0; i < n; i++) {
    result += i < fav[i] || fav[fav[i]] != i ? 0 : dfs(i, fav[i]) + dfs(fav[i], i);
  }

  for (let i = 0; i < n; i++) {
    let j = i;

    if (!seen.has(i)) {
      const m = new Map();

      for (let k = 0; !seen.has(j); k++) {
        seen.add(j);
        m.set(j, k);
        j = fav[j];
      }

      result = Math.max(result, m.size - m.get(j) || 0);
    }
  }

