 * @param {number} target
 * @param {number} maxDoubles
 * @return {number}
 */
var minMoves = function(target, maxDoubles) {
  let moves = 0;
  let current = target;

  while (current > 1 && maxDoubles > 0) {
    if (current % 2 === 0) {
      current /= 2;
      maxDoubles--;
    } else {
      current--;
    }
    moves++;
  }

  return moves + (current - 1);
};

