/**
 * @param {string} corridor
 * @return {number}
 */
var numberOfWays = function(corridor) {
  const MOD = 1e9 + 7;
  let seatCount = 0;
  let result = 1;
  let lastPairEnd = -1;

  for (let i = 0; i < corridor.length; i++) {
    if (corridor[i] === 'S') {
      seatCount++;
    }
  }
  if (seatCount === 0 || seatCount % 2 !== 0) {
    return 0;
  }

  seatCount = 0;

  for (let i = 0; i < corridor.length; i++) {
    if (corridor[i] === 'S') {
      seatCount++;

      if (seatCount % 2 === 0) {
        lastPairEnd = i;
      } else if (seatCount > 1) {
        const plantsCount = i - lastPairEnd - 1;
        result = (result * (plantsCount + 1)) % MOD;
      }
    }
  }

  return result;
};

