  const map = new Map();
  let pairs = 0;

  for (const num of nums) {
    const gcd1 = gcd(num, k);
    for (const [gcd2, count] of map) {
      if ((gcd1 * gcd2) % k === 0) {
        pairs += count;
      }
    }
    map.set(gcd1, (map.get(gcd1) || 0) + 1);
  }

  return pairs;
};

function gcd(a, b) {
  while (b) {
    [a, b] = [b, a % b];
  }
