/**
 * @param {number[]} nums
 * @return {number[]}
 */
var replaceNonCoprimes = function(nums) {
  const result = [];

  for (let num of nums) {
    while (result.length > 0) {
      const last = result[result.length - 1];
      const gcdValue = gcd(last, num);
      if (gcdValue === 1) break;
      result.pop();
      num = (last / gcdValue) * num;
    }
    result.push(num);
  }

  return result;
};

function gcd(a, b) {
  while (b) {
    [a, b] = [b, a % b];
  }
  return a;
}

