/**
 * @param {number[]} nums
 * @return {number}
 */
var halveArray = function(nums) {
  const pq = new PriorityQueue((a, b) => b - a);
  let totalSum = 0;

  for (const num of nums) {
    pq.enqueue(num);
    totalSum += num;
  }

  const target = totalSum / 2;
  let reducedSum = 0;
  let result = 0;

  while (reducedSum < target) {
    const largest = pq.dequeue();
    const halved = largest / 2;
    reducedSum += halved;
    pq.enqueue(halved);
    result++;
  }

  return result;
};

