  const digits = num.toString().split('').map(Number);
  const evenDigits = [];
  const oddDigits = [];

  for (const digit of digits) {
    if (digit % 2 === 0) {
      evenDigits.push(digit);
    } else {
      oddDigits.push(digit);
    }
  }

  evenDigits.sort((a, b) => b - a);
  oddDigits.sort((a, b) => b - a);

  let evenIndex = 0;
  let oddIndex = 0;
