var meetRequirement = function(n, lights, requirement) {
  const brightness = new Array(n).fill(0);
  for (const [position, range] of lights) {
    const start = Math.max(0, position - range);
    const end = Math.min(n - 1, position + range);

    brightness[start]++;
    if (end + 1 < n) {
      brightness[end + 1]--;
    }
  }

