 */
var largestVariance = function(s) {
  const map = new Set(s);
  let result = 0;

  for (const charA of map) {
    for (const charB of map) {
      if (charA === charB) continue;

      let countA = 0;
      let countB = 0;
      let hasA = false;
      let hasB = false;

      for (const char of s) {
        if (char === charA) {
          countA++;
          hasA = true;
        }
        if (char === charB) {
          countB++;
          hasB = true;
        }

        if (hasA && hasB) {
          result = Math.max(result, Math.abs(countA - countB));
        }

        if (countA < countB) {
          countA = 0;
          countB = 0;
          hasA = false;
          hasB = false;
        }
      }

      countA = 0;
      countB = 0;
      hasA = false;
      hasB = false;

      for (let i = s.length - 1; i >= 0; i--) {
        if (s[i] === charA) {
          countA++;
          hasA = true;
        }
        if (s[i] === charB) {
          countB++;
          hasB = true;
        }

        if (hasA && hasB) {
          result = Math.max(result, Math.abs(countA - countB));
        }

        if (countA < countB) {
