var countSubarrays = function(nums, k) {
  let result = 0;
  let currentSum = 0;
  let left = 0;

  for (let right = 0; right < nums.length; right++) {
    currentSum += nums[right];
    while (currentSum * (right - left + 1) >= k) {
      currentSum -= nums[left];
      left++;
    }
    result += right - left + 1;
  }

