  const dp = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));

  for (const [h, w, price] of prices) {
    dp[h][w] = price;
  }

  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      for (let k = 1; k < i; k++) {
        dp[i][j] = Math.max(dp[i][j], dp[k][j] + dp[i - k][j]);
      }
      for (let k = 1; k < j; k++) {
        dp[i][j] = Math.max(dp[i][j], dp[i][k] + dp[i][j - k]);
      }
    }
  }

  return dp[m][n];
};

