  if (n === 1) return 0;

  const minValue = Math.min(...nums);
  const maxValue = Math.max(...nums);
  const minIndex = nums.indexOf(minValue);
  const maxIndex = nums.lastIndexOf(maxValue);
  let result = minIndex + (n - 1 - maxIndex);

  if (minIndex > maxIndex) {
    result -= 1;
  }

  return result;
};

