 * @return {number}
 */
var visibleMountains = function(peaks) {
  const n = peaks.length;

  peaks.sort((a, b) => {
    const leftA = a[0] - a[1];
    const leftB = b[0] - b[1];
    if (leftA === leftB) {
      return (b[0] + b[1]) - (a[0] + a[1]);
    }
    return leftA - leftB;
  });

  let result = 0;
  let maxEnd = -Infinity;

  for (let i = 0; i < n; i++) {
    const [x, y] = peaks[i];
    const rightIntercept = x + y;

    if (rightIntercept > maxEnd) {
      maxEnd = rightIntercept;
      if (i < n - 1 && peaks[i][0] === peaks[i + 1][0] && peaks[i][1] === peaks[i + 1][1]) {
        continue;
      }
      result++;
    }
  }

  return result;
};

