/**
 * @param {number[]} edges
 * @param {number} node1
 * @param {number} node2
 * @return {number}
 */
var closestMeetingNode = function(edges, node1, node2) {
  const n = edges.length;
  const dist1 = new Array(n).fill(Infinity);
  const dist2 = new Array(n).fill(Infinity);

  computeDistances(node1, dist1);
  computeDistances(node2, dist2);

  let minDist = Infinity;
  let result = -1;

  for (let i = 0; i < n; i++) {
    if (dist1[i] !== Infinity && dist2[i] !== Infinity) {
      const maxDist = Math.max(dist1[i], dist2[i]);
      if (maxDist < minDist) {
        minDist = maxDist;
        result = i;
      }
    }
  }

  return result;

  function computeDistances(start, distances) {
    let current = start;
    let steps = 0;
    const visited = new Set();

    while (current !== -1 && !visited.has(current)) {
      distances[current] = steps++;
      visited.add(current);
      current = edges[current];
    }
  }
};

longest-cycle-in-a-graph.solution:
/**
 * @param {number[]} edges
 * @return {number}
 */
var longestCycle = function(edges) {
  const n = edges.length;
  const visited = new Array(n).fill(false);
  let result = -1;

  for (let i = 0; i < n; i++) {
    if (!visited[i]) {
      findCycle(i, 0, []);
    }
  }

  return result;

  function findCycle(node, steps, path) {
    if (visited[node]) {
      const cycleStart = path.indexOf(node);
      if (cycleStart !== -1) {
        result = Math.max(result, steps - cycleStart);
      }
      return;
    }

    visited[node] = true;
    path.push(node);

    if (edges[node] !== -1) {
      findCycle(edges[node], steps + 1, path);
    }

    path.pop();
  }
};

