  let result = 0;

  for (let j = 1; j < nums.length - 1; j++) {
    let i = j - 1;
    let k = j + 1;

    while (i >= 0 && nums[j] - nums[i] <= diff) {
      if (nums[j] - nums[i] === diff) {
        while (k < nums.length && nums[k] - nums[j] <= diff) {
          if (nums[k] - nums[j] === diff) {
