/**
 * @param {number[]} nums
 * @return {number[]}
 */
var smallestSubarrays = function(nums) {
  const n = nums.length;
  const result = new Array(n).fill(1);
  const bitPositions = new Array(32).fill(0);

  for (let i = n - 1; i >= 0; i--) {
    for (let bit = 0; bit < 32; bit++) {
      if (nums[i] & (1 << bit)) {
        bitPositions[bit] = i;
      }
    }

    let maxIndex = i;
    for (let bit = 0; bit < 32; bit++) {
      maxIndex = Math.max(maxIndex, bitPositions[bit]);
    }

    result[i] = maxIndex - i + 1;
  }

  return result;
};

