/**
 * @param {string[]} words
 * @return {number[]}
 */
var sumPrefixScores = function(words) {
  class TrieNode {
    constructor() {
      this.children = new Map();
      this.count = 0;
    }
  }

  const root = new TrieNode();

  for (const word of words) {
    let node = root;
    for (const char of word) {
      if (!node.children.has(char)) {
        node.children.set(char, new TrieNode());
      }
      node = node.children.get(char);
      node.count++;
    }
  }

  const result = [];
  for (const word of words) {
    let node = root;
    let score = 0;
    for (const char of word) {
      node = node.children.get(char);
      score += node.count;
    }
    result.push(score);
  }

  return result;
};

closest-fair-integer.solution:
/**
 * @param {number} n
 * @return {number}
 */
var closestFair = function(n) {
  const digitCount = n.toString().length;
  if (digitCount % 2 === 1) {
    return smallestFairNumberWithLength(digitCount + 1);
  }

  return hasEqualEvenOddDigits(n) ? n : closestFair(n + 1);

  function hasEqualEvenOddDigits(num) {
    const counts = [0, 0];
    while (num > 0) {
      counts[(num % 10) % 2]++;
      num = Math.floor(num / 10);
    }
    return counts[0] === counts[1];
  }

  function smallestFairNumberWithLength(length) {
    let result = '1';
    for (let i = 1; i <= length / 2; i++) {
      result += '0';
    }
    for (let i = length / 2 + 1; i < length; i++) {
      result += '1';
    }
    return parseInt(result);
  }
};

