  while (left < right) {
    if (leftSum === rightSum) {
      left++;
      right--;
      if (left <= right) {
        leftSum = nums[left];
        rightSum = nums[right];
      }
    } else if (leftSum < rightSum) {
      left++;
      leftSum += nums[left];
      result++;
    } else {
      right--;
      rightSum += nums[right];
      result++;
    }
  }

  return result;
};

