  let result = 1;
  let currentGcd = nums[0];

  for (let i = 1; i < n; i++) {
    const newGcd = gcd(currentGcd, nums[i]);
    if (newGcd === 1) {
      result++;
      currentGcd = nums[i];
    } else {
      currentGcd = newGcd;
    }
  }

  return result;

