  while (n > 0) {
    const power = Math.floor(Math.log2(n));
    powers.push(1 << power);
    n -= 1 << power;
  }
  powers.reverse();

  const result = new Array(queries.length);
  for (let i = 0; i < queries.length; i++) {
    const [start, end] = queries[i];
    let product = 1;
    for (let j = start; j <= end; j++) {
      product = (product * powers[j]) % modulo;
    }
    result[i] = product;
  }

  return result;
};

