var oddString = function(words) {
  const map = new Map();
  for (const word of words) {
    const diff = getDiff(word);
    map.set(diff, (map.get(diff) || 0) + 1);
  }

  let oddDiff;
  for (const [diff, count] of map) {
    if (count === 1) {
      oddDiff = diff;
      break;
    }
  }

  for (const word of words) {
    if (getDiff(word) === oddDiff) {
      return word;
