 */
var Allocator = function(n) {
  this.memory = Array(n).fill(0);
};

/**
 * @param {number} size
 * @param {number} mID
 * @return {number}
 */
Allocator.prototype.allocate = function(size, mID) {
  let start = -1;
  let count = 0;

  for (let i = 0; i < this.memory.length; i++) {
    if (this.memory[i] === 0) {
      if (start === -1) start = i;
      count++;
      if (count === size) {
        for (let j = start; j < start + size; j++) {
          this.memory[j] = mID;
        }
        return start;
      }
    } else {
      start = -1;
      count = 0;
    }
  }

  return -1;
};

/**
 * @param {number} mID
 * @return {number}
 */
Allocator.prototype.freeMemory = function(mID) {
  let result = 0;

  for (let i = 0; i < this.memory.length; i++) {
    if (this.memory[i] === mID) {
      this.memory[i] = 0;
      result++;
    }
  }

  return result;
};

