 * @param {number} n
 * @param {number} maxSum
 * @return {number}
 */
var maxCount = function(banned, n, maxSum) {
  const set = new Set(banned);
  let result = 0;
  let currentSum = 0;

  for (let num = 1; num <= n; num++) {
    if (!set.has(num) && currentSum + num <= maxSum) {
      result++;
      currentSum += num;
    }
  }

  return result;
