  function invoke() {
    if (nextArgs) {
      fn(...nextArgs);
      nextArgs = null;
      setTimeout(invoke, t);
    } else {
      isThrottled = false;
    }
  }

  return function(...args) {
    if (isThrottled) {
      nextArgs = args;
      return;
    }

    fn(...args);
    isThrottled = true;
    setTimeout(invoke, t);
  };
};

