maximum-number-of-moves-in-a-grid.solution:
/**
 * @param {number[][]} grid
 * @return {number}
 */
var maxMoves = function(grid) {
  const rows = grid.length;
  const cols = grid[0].length;
  const memo = Array.from({ length: rows }, () => new Array(cols).fill(-1));

  let result = 0;
  for (let row = 0; row < rows; row++) {
    result = Math.max(result, explore(row, 0));
  }

  return result;

  function explore(row, col) {
    if (col === cols - 1) return 0;
    if (memo[row][col] !== -1) return memo[row][col];

    let maxSteps = 0;
    const current = grid[row][col];

    if (row > 0 && col + 1 < cols && grid[row - 1][col + 1] > current) {
      maxSteps = Math.max(maxSteps, 1 + explore(row - 1, col + 1));
    }
    if (col + 1 < cols && grid[row][col + 1] > current) {
      maxSteps = Math.max(maxSteps, 1 + explore(row, col + 1));
    }
    if (row + 1 < rows && col + 1 < cols && grid[row + 1][col + 1] > current) {
      maxSteps = Math.max(maxSteps, 1 + explore(row + 1, col + 1));
    }

    memo[row][col] = maxSteps;
    return maxSteps;
  }
};

count-the-number-of-complete-components.solution:
/**
 * @param {number} n
 * @param {number[][]} edges
 * @return {number}
 */
var countCompleteComponents = function(n, edges) {
  const adjacencyList = Array.from({ length: n }, () => new Set());
  edges.forEach(([a, b]) => {
    adjacencyList[a].add(b);
    adjacencyList[b].add(a);
  });

  const visited = new Set();
  let result = 0;

  function exploreComponent(vertex) {
    const component = new Set([vertex]);
    const queue = [vertex];
    visited.add(vertex);

    while (queue.length) {
      const current = queue.shift();
      adjacencyList[current].forEach(neighbor => {
        if (!visited.has(neighbor)) {
          component.add(neighbor);
          queue.push(neighbor);
          visited.add(neighbor);
        }
      });
    }
    return component;
  }

  function isComplete(component) {
    const size = component.size;
    return [...component].every(vertex =>
      adjacencyList[vertex].size === size - 1
        && [...adjacencyList[vertex]].every(neighbor => component.has(neighbor))
    );
  }

  for (let vertex = 0; vertex < n; vertex++) {
    if (!visited.has(vertex)) {
      const component = exploreComponent(vertex);
      if (isComplete(component)) result++;
    }
  }

  return result;
};

extract-kth-character-from-the-rope-tree.solution:
/**
 * Definition for a rope tree node.
 * class RopeTreeNode {
 *     constructor(len, val, left, right) {
 *         this.len = (len===undefined ? 0 : len);
 *         this.val = (val===undefined ? "" : val);
 *         this.left = (left===undefined ? null : left);
 *         this.right = (right===undefined ? null : right);
 *     }
 * }
 */
/**
 * @param {RopeTreeNode} root
 * @param {number} k
 * @return {character}
 */
var getKthCharacter = function(root, k) {
  if (!root.left && !root.right) {
    return root.val[k - 1];
  }

  const leftLength = getSubtreeLength(root.left);

  if (k <= leftLength) {
    return getKthCharacter(root.left, k);
  } else {
    return getKthCharacter(root.right, k - leftLength);
  }

  function getSubtreeLength(node) {
    if (!node) return 0;
    if (!node.left && !node.right) {
      return node.val.length;
    }
    return node.len;
  }
};

