/**
 * @param {string} s
 * @return {number}
 */
var minLength = function(s) {
  const stack = [];

  for (const char of s) {
    if (stack.length && ((stack[stack.length - 1] === 'A' && char === 'B')
        || (stack[stack.length - 1] === 'C' && char === 'D'))) {
      stack.pop();
    } else {
      stack.push(char);
    }
  }

  return stack.length;
};

