/**
 * @param {string} s
 * @return {string}
 */
var makeSmallestPalindrome = function(s) {
  const chars = s.split('');
  let left = 0;
  let right = s.length - 1;

  while (left < right) {
    if (chars[left] !== chars[right]) {
      chars[left] = chars[right] = chars[left] < chars[right] ? chars[left] : chars[right];
    }
    left++;
    right--;
  }

  return chars.join('');
};

find-the-punishment-number-of-an-integer.solution:
/**
 * @param {number} n
 * @return {number}
 */
var punishmentNumber = function(n) {
  function canPartition(num, target, start) {
    if (!target && start === num.length) {
      return true;
    } else if (start >= num.length) {
      return false;
    }
    for (let i = start, sum = 0; i < num.length; i++) {
      sum = sum * 10 + +num[i];
      if (sum > target) {
        break;
      } else if (canPartition(num, target - sum, i + 1)) {
        return true;
      }
    }

    return false;
  }

  let result = 0;
  for (let i = 1; i <= n; i++) {
    if (canPartition((i * i).toString(), i, 0)) {
      result += i * i;
    }
  }

  return result;
};

differences-between-two-objects.solution:
/**
 * @param {Object|Array} obj1
 * @param {Object|Array} obj2
 * @return {Object|Array}
 */
function objDiff(obj1, obj2) {
  if (obj1 === obj2) return {};

  if (obj1 === null || obj2 === null || typeof obj1 !== typeof obj2
    || typeof obj1 !== 'object') {
    return [obj1, obj2];
  }

  if (Array.isArray(obj1) !== Array.isArray(obj2)) {
    return [obj1, obj2];
  }

  const result = {};
  for (const key in obj1) {
    if (key in obj2) {
      const difference = objDiff(obj1[key], obj2[key]);
      if (Object.keys(difference).length > 0 || Array.isArray(difference)) {
        result[key] = difference;
      }
    }
  }

  return result;
}

minimum-operations-to-make-numbers-non-p.solution:
/**
 * @param {number[]} nums
 * @param {number} x
 * @param {number} y
 * @return {number}
 */
var minOperations = function(nums, x, y) {
  let left = 0;
  let right = Math.max(...nums);

  while (left < right) {
    const mid = Math.floor((left + right) / 2);
    if (canMakeNonPositive(nums, x, y, mid)) {
      right = mid;
    } else {
      left = mid + 1;
    }
  }

  return left;

  function canMakeNonPositive(nums, x, y, operations) {
    const n = nums.length;
    const remaining = nums.map(num => num - operations * y);

    let totalExtraNeeded = 0;
    for (let i = 0; i < n; i++) {
      if (remaining[i] > 0) {
        const extraNeeded = Math.ceil(remaining[i] / (x - y));
        totalExtraNeeded += extraNeeded;
      }
    }

    return totalExtraNeeded <= operations;
  }
};

