/**
 * @param {string} s
 * @param {string[]} dictionary
 * @return {number}
 */
var minExtraChar = function(s, dictionary) {
  const n = s.length;
  const dp = new Array(n + 1).fill(Infinity);
  dp[0] = 0;
  const dictSet = new Set(dictionary);

  for (let i = 1; i <= n; i++) {
    dp[i] = dp[i - 1] + 1;
    for (let j = 0; j < i; j++) {
      if (dictSet.has(s.slice(j, i))) {
        dp[i] = Math.min(dp[i], dp[j]);
      }
    }
  }

  return dp[n];
};

greatest-common-divisor-traversal.solution:
/**
 * @param {number[]} nums
 * @return {boolean}
 */
var canTraverseAllPairs = function(nums) {
  if (nums.length === 1) return true;
  const n = nums.length;
  const maxNum = Math.max(...nums);
  const parent = new Array(maxNum + 1).fill().map((_, i) => i);
  const rank = new Array(maxNum + 1).fill(0);

  const primeToIndex = new Map();
  for (let i = 0; i < n; i++) {
    if (nums[i] === 1) return false;
    const factors = getPrimeFactors(nums[i]);
    for (const prime of factors) {
      if (primeToIndex.has(prime)) {
        union(primeToIndex.get(prime), i);
      } else {
        primeToIndex.set(prime, i);
      }
    }
  }

  const root = find(0);
  for (let i = 1; i < n; i++) {
    if (find(i) !== root) return false;
  }

  return true;

  function find(x) {
    if (parent[x] !== x) {
      parent[x] = find(parent[x]);
    }
    return parent[x];
  }

  function union(x, y) {
    const px = find(x);
    const py = find(y);
    if (px === py) return;
    if (rank[px] < rank[py]) {
      parent[px] = py;
    } else if (rank[px] > rank[py]) {
      parent[py] = px;
    } else {
      parent[py] = px;
      rank[px]++;
    }
  }

  function getPrimeFactors(num) {
    const factors = [];
    for (let i = 2; i * i <= num; i++) {
      if (num % i === 0) {
        factors.push(i);
        while (num % i === 0) num /= i;
      }
    }
    if (num > 1) factors.push(num);
    return factors;
  }
};

