find-the-closest-marked-node.solution:
/**
 * @param {number} n
 * @param {number[][]} edges
 * @param {number} s
 * @param {number[]} marked
 * @return {number}
 */
var minimumDistance = function(n, edges, s, marked) {
  const graph = new Array(n).fill().map(() => []);
  const markedSet = new Set(marked);

  for (const [u, v, w] of edges) {
    graph[u].push([v, w]);
  }

  const distances = new Array(n).fill(Infinity);
  const pq = new PriorityQueue((a, b) => a[0] - b[0]);
  distances[s] = 0;
  pq.enqueue([0, s]);

  while (!pq.isEmpty()) {
    const [currentDist, node] = pq.dequeue();

    if (currentDist > distances[node]) continue;

    if (markedSet.has(node)) {
      return currentDist;
    }

    for (const [neighbor, weight] of graph[node]) {
      const newDist = currentDist + weight;
      if (newDist < distances[neighbor]) {
        distances[neighbor] = newDist;
        pq.enqueue([newDist, neighbor]);
      }
    }
  }

  return -1;
};

