number-of-beautiful-pairs.solution:
/**
 * @param {number[]} nums
 * @return {number}
 */
var countBeautifulPairs = function(nums) {
  let result = 0;
  for (let i = 0; i < nums.length - 1; i++) {
    for (let j = i + 1; j < nums.length; j++) {
      const first = getFirstDigit(nums[i]);
      const last = getLastDigit(nums[j]);
      if (gcd(first, last) === 1) {
        result++;
      }
    }
  }

  return result;

  function gcd(a, b) {
    while (b) {
      a %= b;
      [a, b] = [b, a];
    }
    return a;
  }

  function getFirstDigit(num) {
    while (num >= 10) {
      num = Math.floor(num / 10);
    }
    return num;
  }

  function getLastDigit(num) {
    return num % 10;
  }
};

minimum-operations-to-make-the-integer-z.solution:
/**
 * @param {number} num1
 * @param {number} num2
 * @return {number}
 */
var makeTheIntegerZero = function(num1, num2) {
  for (let operations = 1; operations <= 60; operations++) {
    const remaining = num1 - num2 * operations;

    if (remaining < operations) {
      return -1;
    }

    if (operations >= countBits(remaining)) {
      return operations;
    }
  }

  return -1;

  function countBits(n) {
    let count = 0;
    while (n > 0) {
      count += n & 1;
      n = Math.floor(n / 2);
    }
    return count;
  }
};

robot-collisions.solution:
/**
 * @param {number[]} positions
 * @param {number[]} healths
 * @param {string} directions
 * @return {number[]}
 */
var survivedRobotsHealths = function(positions, healths, directions) {
  const n = positions.length;
  const robots = Array.from({ length: n }, (_, i) => ({
    index: i,
    position: positions[i],
    health: healths[i],
    direction: directions[i]
  }));

  robots.sort((a, b) => a.position - b.position);

  const stack = [];
  for (const robot of robots) {
    if (robot.direction === 'R') {
      stack.push(robot);
      continue;
    }

    while (stack.length && stack[stack.length - 1].direction === 'R' && robot.health > 0) {
      const last = stack[stack.length - 1];
      if (last.health === robot.health) {
        stack.pop();
        robot.health = 0;
      } else if (last.health > robot.health) {
        last.health--;
        robot.health = 0;
      } else {
        stack.pop();
        robot.health--;
      }
    }
    if (robot.health > 0) {
      stack.push(robot);
    }
  }

  const result = new Array(n).fill(0);
  for (const robot of stack) {
    result[robot.index] = robot.health;
  }

  return result.filter(health => health > 0);
};

