/**
 * Definition for a street.
 * class Street {
 *     @param {number[]} doors
 *     constructor(doors);
 *
 *     @return {void}
 *     closeDoor();
 *
 *     @return {boolean}
 *     isDoorOpen();
 *
 *     @return {void}
 *     moveRight();
 * }
 */
/**
 * @param {Street} street
 * @param {number} k
 * @return {number}
 */
var houseCount = function(street, k) {
  let result = 0;

  while (true) {
    tryMoveToOpen(street, k, true);
    const distance = tryMoveToOpen(street, k, false);

    if (distance > k) {
      return result;
    }

    result = distance;
    street.closeDoor();
  }

  function tryMoveToOpen(street, k, considerCurrent) {
    if (street.isDoorOpen() && considerCurrent) {
      return 0;
    }

    let moves = 1;
    street.moveRight();

    while (!street.isDoorOpen() && moves <= k) {
      street.moveRight();
      moves++;
    }

    return moves;
  }
};

