/**
 * @param {number[]} nums
 * @return {number}
 */
var sumImbalanceNumbers = function(nums) {
  const n = nums.length;
  let result = 0;

  for (let i = 0; i < n; i++) {
    const seen = new Set();
    let imbalance = 0;

    for (let j = i; j < n; j++) {
      const current = nums[j];

      if (!seen.has(current)) {
        const hasNext = seen.has(current + 1);
        const hasPrev = seen.has(current - 1);

        if (hasNext && hasPrev) {
          imbalance--;
        } else if (!hasNext && !hasPrev && seen.size > 0) {
          imbalance++;
        }

        seen.add(current);
      }

      result += imbalance;
    }
  }

  return result;
};

