Array.prototype.upperBound = function(target) {
  let left = 0;
  let right = this.length - 1;
  let result = -1;

  while (left <= right) {
    const mid = Math.floor((left + right) / 2);

    if (this[mid] === target) {
      result = mid;
      left = mid + 1;
    } else if (this[mid] < target) {
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }

  return result;
};

