/**
 * @param {number} n
 * @param {number} x
 * @return {number}
 */
var numberOfWays = function(n, x) {
  const MOD = 1e9 + 7;
  const dp = new Array(n + 1).fill(0);
  dp[0] = 1;

  let power = 1;
  while (Math.pow(power, x) <= n) {
    const currentPower = Math.pow(power, x);
    for (let sum = n; sum >= currentPower; sum--) {
      dp[sum] = (dp[sum] + dp[sum - currentPower]) % MOD;
    }
    power++;
  }

  return dp[n];
};

