const intervalMap = new Map();
let nextId = 1;

/**
 * @param {Function} fn
 * @param {number} delay
 * @param {number} period
 * @return {number} id
 */
function customInterval(fn, delay, period) {
  let count = 0;
  const id = nextId++;

  function scheduleNext() {
    const nextDelay = delay + period * count;
    const timeoutId = setTimeout(() => {
      fn();
      count++;
      scheduleNext();
    }, nextDelay);
    intervalMap.set(id, timeoutId);
  }

  scheduleNext();
  return id;
}

/**
 * @param {number} id
 * @return {void}
 */
function customClearInterval(id) {
  const timeoutId = intervalMap.get(id);
  if (timeoutId) {
    clearTimeout(timeoutId);
    intervalMap.delete(id);
  }
}

insert-greatest-common-divisors-in-linke.solution:
/**
 * Definition for singly-linked list.
 * function ListNode(val, next) {
 *     this.val = (val===undefined ? 0 : val)
 *     this.next = (next===undefined ? null : next)
 * }
 */
/**
 * @param {ListNode} head
 * @return {ListNode}
 */
var insertGreatestCommonDivisors = function(head) {
  let current = head;
  while (current && current.next) {
    const nextNode = current.next;
    const divisor = gcd(current.val, nextNode.val);
    current.next = new ListNode(divisor, nextNode);
    current = nextNode;
  }
  return head;

  function gcd(a, b) {
    while (b) {
      a %= b;
      [a, b] = [b, a];
    }
    return a;
  }
};

