  const map = new Map();

  for (const num of nums) {
    const maxDigit = getMaxDigit(num);
    if (!map.has(maxDigit)) {
      map.set(maxDigit, []);
    }
    map.get(maxDigit).push(num);
  }

  for (const numbers of map.values()) {
    if (numbers.length >= 2) {
      numbers.sort((a, b) => b - a);
      result = Math.max(result, numbers[0] + numbers[1]);
    }
  }

  return result;

  function getMaxDigit(num) {
    let max = 0;
    while (num > 0) {
      max = Math.max(max, num % 10);
      num = Math.floor(num / 10);
    }
    return max;
  }
};

double-a-number-represented-as-a-linked-.solution:
/**
 * Definition for singly-linked list.
 * function ListNode(val, next) {
 *     this.val = (val===undefined ? 0 : val)
 *     this.next = (next===undefined ? null : next)
 * }
 */
/**
 * @param {ListNode} head
 * @return {ListNode}
 */
var doubleIt = function(head) {
  const reversed = reverseList(head);
  let carry = 0;
  let current = reversed;
  let prev = null;

  while (current) {
    const doubled = current.val * 2 + carry;
    current.val = doubled % 10;
    carry = Math.floor(doubled / 10);
    prev = current;
    current = current.next;
  }

  if (carry) {
    prev.next = new ListNode(carry);
  }

  return reverseList(reversed);

  function reverseList(node) {
    let prev = null;
    let current = node;
    while (current) {
      const next = current.next;
      current.next = prev;
      prev = current;
      current = next;
    }
    return prev;
  }
};

apply-operations-to-maximize-score.solution:
/**
 * @param {number[]} nums
 * @param {number} k
 * @return {number}
 */
var maximumScore = function(nums, k) {
  const MOD = 1000000007n;
  const MAX = 100000;
  const powerCache = {};

  const primeScores = new Array(MAX + 1).fill(0);
  for (let prime = 2; prime <= MAX; prime++) {
    if (primeScores[prime] > 0) continue;
    for (let multiple = prime; multiple <= MAX; multiple += prime) {
      primeScores[multiple]++;
    }
  }

  const elements = nums.map(num => [num, primeScores[num], 1]);

  const stack = [-1];
  const n = elements.length;

  for (let i = 0; i <= n; i++) {
    while (
      stack.length > 1 && (i === n || elements[stack[stack.length - 1]][1] < elements[i][1])
    ) {
      const current = stack.pop();
      elements[current][2] = (i - current) * (current - stack[stack.length - 1]);
    }

    stack.push(i);
  }

  elements.sort((a, b) => b[0] - a[0]);

  let result = 1n;
  let remainingOps = k;

  for (let i = 0; remainingOps > 0; i++) {
    const usedOps = Math.min(remainingOps, elements[i][2]);
    remainingOps -= usedOps;

    const cacheKey = `${elements[i][0]},${usedOps}`;
    let power;

    if (cacheKey in powerCache) {
      power = powerCache[cacheKey];
    } else {
      let base = BigInt(elements[i][0]);
      let exp = usedOps;
      power = 1n;

      while (exp > 0) {
        if (exp & 1) {
          power = (power * base) % MOD;
        }
        exp >>= 1;
        base = (base * base) % MOD;
      }

      powerCache[cacheKey] = power;
    }

    result = (result * power) % MOD;
  }

  return Number(result);
};

