  dp[0][0] = 0;

  for (let i = 0; i < n; i++) {
    for (let prev = 0; prev <= 3; prev++) {
      for (let curr = 1; curr <= 3; curr++) {
        if (curr >= prev) {
          dp[i + 1][curr] = Math.min(
