  const map = new Map();
  let subarraySum = 0;
  let result = 0;

  for (let i = 0; i < k; i++) {
    map.set(nums[i], (map.get(nums[i]) || 0) + 1);
    subarraySum += nums[i];
  }

  if (map.size >= m) {
    result = subarraySum;
  }

  for (let i = k; i < nums.length; i++) {
    map.set(nums[i - k], map.get(nums[i - k]) - 1);
    if (map.get(nums[i - k]) === 0) {
      map.delete(nums[i - k]);
    }

    map.set(nums[i], (map.get(nums[i]) || 0) + 1);
    subarraySum = subarraySum - nums[i - k] + nums[i];

    if (map.size >= m) {
      result = Math.max(result, subarraySum);
    }
  }

  return result;
};

