  return result;

  function dfs(node, par, dep) {
    parent[node] = par;
    depth[node] = dep;
    for (const [next, w] of graph[node]) {
      if (next !== par) {
        weightCount[next] = [...weightCount[node]];
        weightCount[next][w]++;
        dfs(next, node, dep + 1);
      }
    }
  }
  function lca(u, v) {
    if (depth[u] < depth[v]) [u, v] = [v, u];
    while (depth[u] > depth[v]) u = parent[u];
    while (u !== v) {
      u = parent[u];
      v = parent[v];
    }
    return u;
  }
};

