var maxSum = function(nums, k) {
  const MOD = 1e9 + 7;
  const bitCounts = new Array(30).fill(0);

  for (const num of nums) {
    for (let i = 0; i < 30; i++) {
      if (num & (1 << i)) bitCounts[i]++;
    }
  }

  let result = 0;
  for (let i = 0; i < k; i++) {
    let current = 0;
    for (let j = 29; j >= 0; j--) {
      if (bitCounts[j] > 0) {
        current |= (1 << j);
        bitCounts[j]--;
      }
    }
    result = (result + Number((BigInt(current) * BigInt(current)) % BigInt(MOD))) % MOD;
  }

  return result;
};

