var minimumSum = function(nums) {
  const n = nums.length;
  const leftMin = new Array(n).fill(Infinity);
  const rightMin = new Array(n).fill(Infinity);

  leftMin[0] = nums[0];
  for (let i = 1; i < n; i++) {
    leftMin[i] = Math.min(leftMin[i - 1], nums[i]);
  }

  rightMin[n - 1] = nums[n - 1];
