/**
 * Definition for BigArray.
 * class BigArray {
 *     @param {number[]} elements
 *     constructor(elements);
 *
 *     @param {number} index
 *     @return {number}
 *     at(index);
 *
 *     @return {number}
 *     size();
 * }
 */
/**
 * @param {BigArray} nums
 * @return {number}
 */
var countBlocks = function(nums) {
  const n = nums.size();
  if (n === 0) return 0;

  let blocks = 1;
  let currentIndex = 0;

  while (currentIndex < n - 1) {
    const nextBlockStart = findNextBlockStart(nums, currentIndex, n);
    if (nextBlockStart < n) {
      blocks++;
      currentIndex = nextBlockStart;
    } else {
      break;
    }
  }

  return blocks;

  function findNextBlockStart(nums, startIndex, n) {
    const currentValue = nums.at(startIndex);
    let left = startIndex + 1;
    let right = n;

    while (left < right) {
      const mid = Math.floor((left + right) / 2);
      if (nums.at(mid) === currentValue) {
        left = mid + 1;
      } else {
        right = mid;
      }
    }

    return left;
  }
};

