  const n = s.length;
  const prefixCounts = new Array(26).fill().map(() => new Array(n + 1).fill(0));

  for (let i = 0; i < n; i++) {
    const charIndex = s.charCodeAt(i) - 97;
    for (let j = 0; j < 26; j++) {
      prefixCounts[j][i + 1] = prefixCounts[j][i];
