/**
 * @param {number[]} nums
 * @param {number} k
 * @return {boolean}
 */
var hasIncreasingSubarrays = function(nums, k) {
  for (let i = 0; i <= nums.length - 2 * k; i++) {
    if (helper(i, k) && helper(i + k, k)) {
      return true;
    }
  }

  return false;

  function helper(start, length) {
    for (let i = start; i < start + length - 1; i++) {
      if (nums[i] >= nums[i + 1]) return false;
    }
    return true;
  }
};

