var countValidSelections = function(nums) {
  const n = nums.length;
  let result = 0;

  for (let i = 0; i < n; i++) {
    if (nums[i] === 0) {
      if (helper(i, -1)) result++;
      if (helper(i, 1)) result++;
    }
  }

  return result;

  function helper(startIndex, direction) {
    const arr = [...nums];
    let current = startIndex;
    let dir = direction;

    while (current >= 0 && current < n) {
      if (arr[current] === 0) {
        current += dir;
      } else {
        arr[current]--;
        dir = -dir;
        current += dir;
      }
    }

    return arr.every(val => val === 0);
  }
};

