    if (right + 1 < nums.length) {
      maxDecrements[right + 1]--;
    }
  }

  let currentDecrements = 0;
  for (let i = 0; i < nums.length; i++) {
    currentDecrements += maxDecrements[i];
    if (nums[i] > currentDecrements) {
      return false;
    }
  }

  return true;
};

