/**
 * @param {number[][]} grid
 * @return {number[][]}
 */
var sortMatrix = function(grid) {
  const n = grid.length;
  const map = new Map();

  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      const key = i - j;
      if (!map.has(key)) {
        map.set(key, key < 0
          ? new PriorityQueue((a, b) => a - b)
          : new PriorityQueue((a, b) => b - a));
      }
      map.get(key).enqueue(grid[i][j]);
    }
  }

  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      const key = i - j;
      grid[i][j] = map.get(key).dequeue();
    }
  }

  return grid;
};

