  const map = new Map();

  for (const [skill, profit] of tasks) {
    if (!map.has(skill)) {
      map.set(skill, []);
    }
    map.get(skill).push(profit);
  }

  for (const [skill, profits] of map) {
    profits.sort((a, b) => b - a);
