  let result = 1;
  for (let i = 2; i < complexity.length; i++) {
    result = (result * i) % MOD;
  }

  return result;
};

count-partitions-with-max-min-difference.solution:
/**
 * @param {number[]} nums
 * @param {number} k
 * @return {number}
 */
var countPartitions = function(nums, k) {
  const MOD = 1e9 + 7;
  const n = nums.length;
  const dp = new Array(n + 1).fill(0);
  dp[0] = 1;

  let sum = 1;
  const minQueue = [];
  const maxQueue = [];

  for (let left = 0, right = 0; right < n; right++) {
    while (maxQueue.length && nums[right] > nums[maxQueue.at(-1)]) maxQueue.pop();
    maxQueue.push(right);

    while (minQueue.length && nums[right] < nums[minQueue.at(-1)]) minQueue.pop();
    minQueue.push(right);

    while (nums[maxQueue[0]] - nums[minQueue[0]] > k) {
      sum = (sum - dp[left++] + MOD) % MOD;
      if (minQueue[0] < left) minQueue.shift();
      if (maxQueue[0] < left) maxQueue.shift();
    }

    dp[right + 1] = sum;
    sum = (sum + dp[right + 1]) % MOD;
  }

  return dp[n];
};

count-special-triplets.solution:
/**
 * @param {number[]} nums
 * @return {number}
 */
var specialTriplets = function(nums) {
  const MOD = 1e9 + 7;
  let result = 0;

  const leftCount = new Map();
  const rightCount = new Map();
  for (const num of nums) {
    rightCount.set(num, (rightCount.get(num) || 0) + 1);
  }

  for (let j = 0; j < nums.length; j++) {
    const middle = nums[j];
    const target = middle * 2;

    rightCount.set(middle, rightCount.get(middle) - 1);
    if (rightCount.get(middle) === 0) {
      rightCount.delete(middle);
    }

    const left = leftCount.get(target) || 0;
    const right = rightCount.get(target) || 0;
    result = (result + left * right) % MOD;
    leftCount.set(middle, (leftCount.get(middle) || 0) + 1);
  }

  return result;
};

coupon-code-validator.solution:
/**
 * @param {string[]} code
 * @param {string[]} businessLine
 * @param {boolean[]} isActive
 * @return {string[]}
 */
var validateCoupons = function(code, businessLine, isActive) {
  const whitelist = ['electronics', 'grocery', 'pharmacy', 'restaurant'];
  const order = { electronics: 0, grocery: 1, pharmacy: 2, restaurant: 3 };

  return code
    .map((id, i) => ({ id, name: businessLine[i], active: isActive[i] }))
    .filter(({ id, name, active }) => active && whitelist.includes(name) && /^[\da-z_]+$/i.test(id))
    .sort((a, b) => {
      const compare = order[a.name] - order[b.name];
      if (compare !== 0) return compare;
      return a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
    })
    .map(({ id }) => id);
};

